/// Unit-test seam for the instance-hypothesis lowering (`InstanceHypothesisSites`).
/// Not present in production builds.
#[cfg(test)]
pub(crate) fn lower_to_trust_ir_functions_with_test_instance_hypotheses(
    module_name: impl Into<String>,
    funcs: &[VerifiableFunction],
    instance_hypothesis_sites: &InstanceHypothesisSites,
) -> Result<Module, BridgeError> {
    lower_to_trust_ir_functions_impl(
        module_name,
        funcs,
        &FxHashSet::default(),
        &FxHashSet::default(),
        &FxHashSet::default(),
        &FxHashSet::default(),
        &FxHashSet::default(),
        &FxHashSet::default(),
        &FxHashSet::default(),
        &FxHashSet::default(),
        &FxHashSet::default(),
        &CallReachWithdrawals::default(), // no call-reach withdrawals
        None,
        instance_hypothesis_sites,
        &CompilerAllocGrowPins::default(),
    )
}

