    #[test]
    fn slice_index_projected_store_uses_data_lane() {
        let slice_ty =
            Ty::Ref { mutable: true, inner: Box::new(Ty::Slice { elem: Box::new(Ty::u8()) }) };
        let func = unit_function(
            "trust_ir_slice_index_store",
            vec![
                LocalDecl { index: 0, ty: Ty::Unit, name: None },
                LocalDecl { index: 1, ty: slice_ty, name: Some("slice".into()) },
                LocalDecl { index: 2, ty: Ty::usize(), name: Some("idx".into()) },
                LocalDecl { index: 3, ty: Ty::u8(), name: Some("value".into()) },
            ],
            vec![Statement::Assign {
                place: Place {
                    local: 1,
                    projections: vec![Projection::Deref, Projection::Index(2)],
                },
                rvalue: Rvalue::Use(Operand::Copy(Place::local(3))),
                span: SourceSpan::default(),
            }],
        );

        let module = lower_to_trust_ir(&func).expect("slice index projected store should lower");
        let bb0 = &module.functions[0].blocks[0];
        // Trust (B2-1b): the data lane is the FORMAT's own PtrData on the
        // first-class slice fat spelling (the anonymous ExtractField{Ptr, field:0}
        // tuple projection retired).
        let fat_ty = slice_fat_ty(&module, &TrustIrTy::U8);
        assert!(
            bb0.body.iter().any(|node| matches!(
                &node.inst,
                Inst::PtrData { ptr_ty, .. } if *ptr_ty == fat_ty
            )),
            "slice store should extract the data pointer lane"
        );
        assert!(
            bb0.body.iter().any(|node| matches!(node.inst, Inst::GEP { .. })),
            "slice store should address the selected element"
        );
        assert!(
            bb0.body.iter().any(|node| matches!(node.inst, Inst::Store { ty: TrustIrTy::U8, .. })),
            "slice store should write the element type"
        );
    }

    #[test]
    fn slice_constant_index_from_end_store_uses_metadata_lane() {
        let slice_ty =
            Ty::Ref { mutable: true, inner: Box::new(Ty::Slice { elem: Box::new(Ty::u8()) }) };
        let func = unit_function(
            "trust_ir_slice_constant_index_store",
            vec![
                LocalDecl { index: 0, ty: Ty::Unit, name: None },
                LocalDecl { index: 1, ty: slice_ty, name: Some("slice".into()) },
                LocalDecl { index: 2, ty: Ty::u8(), name: Some("value".into()) },
            ],
            vec![Statement::Assign {
                place: Place {
                    local: 1,
                    projections: vec![
                        Projection::Deref,
                        Projection::ConstantIndex { offset: 1, min_length: 1, from_end: true },
                    ],
                },
                rvalue: Rvalue::Use(Operand::Copy(Place::local(2))),
                span: SourceSpan::default(),
            }],
        );

        let module = lower_to_trust_ir(&func).expect("slice from_end projected store should lower");
        let bb0 = &module.functions[0].blocks[0];
        // Trust (B2-1b): the length lane is the FORMAT's own PtrMetadata at the
        // canonical U64 metadata type, and the len - offset arithmetic matches it
        // (the anonymous ExtractField{I64, field:1} lane + I64 Sub retired).
        let fat_ty = slice_fat_ty(&module, &TrustIrTy::U8);
        assert!(
            bb0.body.iter().any(|node| matches!(
                &node.inst,
                Inst::PtrMetadata { ptr_ty, metadata_ty: TrustIrTy::U64, .. } if *ptr_ty == fat_ty
            )),
            "from_end slice store should extract the length metadata lane"
        );
        assert!(
            bb0.body.iter().any(|node| matches!(
                node.inst,
                Inst::BinOp { op: TrustIrBinOp::Sub, ty: TrustIrTy::U64, .. }
            )),
            "from_end slice store should compute len - offset"
        );
        assert!(bb0.body.iter().any(|node| matches!(node.inst, Inst::Store { .. })));
    }

    #[test]
    fn adt_active_field_aggregate_lowers_as_sound_havoc() {
        let union_like_ty = Ty::Adt {
            adt_kind: None,
            layout: None,
            variants: Vec::new().into(),
            name: "UnionLike".into(),
            fields: vec![("a".into(), Ty::i32()), ("b".into(), Ty::i64())].into(),
            disc_index_safe: false,
            faithful_enum_repr: None,
            enum_layout: None,
            arbitrary_precision: None,
            validity_wrapper: None,
        };
        let func = unit_function(
            "trust_ir_adt_active_field",
            vec![
                LocalDecl { index: 0, ty: Ty::Unit, name: None },
                LocalDecl { index: 1, ty: union_like_ty, name: None },
            ],
            vec![Statement::Assign {
                place: Place::local(1),
                rvalue: Rvalue::Aggregate(
                    AggregateKind::Adt {
                        name: "UnionLike".into(),
                        variant: 0,
                        active_field: Some(1),
                        args: None,
                    },
                    vec![Operand::Constant(ConstValue::Int(7))],
                ),
                span: SourceSpan::default(),
            }],
        );

        // R145: a union construction lowers as a pure havoc `Undef` of the
        // union type (the Coroutine-frame treatment): the written field is
        // NOT threaded into a modeled fact — no InsertField, no field-typed
        // Store — so nothing about the union's contents is ever provable
        // from the construction; reads route through the R140 opaque-scalar
        // transmute path or fail-closed projections.
        let module = lower_to_trust_ir(&func)
            .expect("a union construction should lower as sound havoc (R145)");
        let body: Vec<_> = module.functions[0].blocks.iter().flat_map(|b| b.body.iter()).collect();
        assert!(
            body.iter().any(|node| matches!(&node.inst, Inst::Undef { .. })
                && node.proofs.contains(&trust_ir::ProofAnnotation::FreshSymbolicHavoc)),
            "the union value must be a fresh symbolic havoc"
        );
        assert!(
            !body.iter().any(|node| matches!(&node.inst, Inst::InsertField { .. })),
            "the union construction must not model a field write"
        );
    }

