    #[test]
    fn operand_const_nonneg_reads_literal_sizes() {
        assert_eq!(operand_const_nonneg(&Operand::Constant(ConstValue::Uint(2, 64))), Some(2));
        assert_eq!(operand_const_nonneg(&Operand::Constant(ConstValue::Uint(0, 64))), Some(0));
        assert_eq!(operand_const_nonneg(&Operand::Constant(ConstValue::Int(3))), Some(3));
        // Negative and non-literal operands are not extractable → caller fails closed.
        assert_eq!(operand_const_nonneg(&Operand::Constant(ConstValue::Int(-1))), None);
        assert_eq!(operand_const_nonneg(&Operand::Copy(Place::local(0))), None);
    }

