    #[test]
    fn next_accepts_total_adapters_over_slice_base() {
        // A chain of TOTAL adapters (Rev/Copied/Take/Skip/Enumerate/Peekable) over a
        // slice iterator runs no user code — accepted (recursively).
        for name in [
            "std::iter::Rev",
            "core::iter::Copied",
            "std::iter::Take",
            "std::iter::Skip",
            "std::iter::Enumerate",
            "std::iter::Peekable",
        ] {
            assert!(
                ty_is_slice_iterator_receiver(&Ty::Ref {
                    mutable: true,
                    inner: Box::new(adapter(name, slice_iter_adt())),
                }),
                "{name} over slice::Iter should be slice-backed"
            );
        }
        // Nested total adapters: `Rev<Copied<slice::Iter>>`.
        assert!(ty_is_slice_iterator_receiver(&adapter(
            "std::iter::Rev",
            adapter("std::iter::Copied", slice_iter_adt()),
        )));
    }

    #[test]
    fn next_rejects_total_adapter_over_nonslice_or_closure_inner() {
        // A total adapter is only slice-backed when its INNER is — `Rev<Map<…>>` and
        // `Rev<MyIter>` must be rejected (the inner next() can run user code/panic).
        assert!(!ty_is_slice_iterator_receiver(&adapter(
            "std::iter::Rev",
            adapter("std::iter::Map", slice_iter_adt()),
        )));
        assert!(!ty_is_slice_iterator_receiver(&adapter(
            "std::iter::Rev",
            Ty::Adt {
                adt_kind: None,
                layout: None,
                variants: Vec::new().into(),
                name: "my_crate::MyIter".into(),
                fields: vec![].into(),
                disc_index_safe: false,
                faithful_enum_repr: None,
                enum_layout: None,
                arbitrary_precision: None,
                validity_wrapper: None,
            },
        )));
        // `Cloned` is NOT total (runs `T::clone`, which a user impl can panic in).
        assert!(!ty_is_slice_iterator_receiver(&adapter("std::iter::Cloned", slice_iter_adt(),)));
        // A total adapter with no slice-backed field (empty inner) is rejected.
        assert!(!ty_is_slice_iterator_receiver(&Ty::Adt {
            adt_kind: None,
            layout: None,
            variants: Vec::new().into(),
            name: "std::iter::Rev".into(),
            fields: vec![].into(),
            disc_index_safe: false,
            faithful_enum_repr: None,
            enum_layout: None,
            arbitrary_precision: None,
            validity_wrapper: None,
        }));
    }

