    fn primitive_comparison_sentinel_requires_exact_wire_identity() {
        let sentinel = trust_types::total_call_summaries::TRUST_TOTAL_CLONE_SENTINEL;
        assert!(total_no_panic_call_summary(sentinel));
        assert!(!total_no_panic_call_summary(&format!("my_crate::{sentinel}")));
        assert!(!total_no_panic_call_summary(&format!("{sentinel}::suffix")));
    }

    #[test]
    fn scalar_ascii_predicates_are_total_via_exact_path() {
        // The siblings not yet retired by step 2b retain their exact-path
        // summaries. This does not authorize reinstating the nine operations
        // whose actual bundled bodies now carry their calls and obligations.
        for callee in [
            "core::num::<impl u8>::is_ascii_alphanumeric",
            "core::num::<impl u8>::to_ascii_lowercase",
            "core::char::methods::<impl char>::is_alphanumeric",
            "core::char::methods::<impl char>::is_whitespace",
            "core::char::methods::<impl char>::to_ascii_uppercase",
        ] {
            assert!(total_no_panic_call_summary(callee), "expected scalar-ascii total: {callee}");
        }
        for callee in [
            "std::num::<impl u8>::is_ascii",
            "core::num::<impl u8>::is_ascii_digit",
            "core::num::<impl u8>::is_ascii_alphabetic",
            "core::num::<impl u8>::is_ascii_whitespace",
            "core::num::<impl u8>::is_ascii_uppercase",
            "core::num::<impl u8>::is_ascii_lowercase",
            "core::num::<impl u8>::is_ascii_hexdigit",
            "core::char::methods::<impl char>::is_ascii",
            "core::char::methods::<impl char>::is_ascii_digit",
        ] {
            assert!(
                !total_no_panic_call_summary(callee),
                "step-2b body authority must not be replaced by an exact-path summary: {callee}"
            );
        }
        // Fail closed: a hostile middle segment, `str` (allocates), a non-std root,
        // a non-ASCII `num` method, and `char::to_lowercase` (returns an iterator)
        // must NOT gain totality.
        for callee in [
            "core::hostile::num::is_ascii_digit",
            "core::str::<impl str>::to_ascii_lowercase",
            "mycrate::char::methods::is_alphanumeric",
            // NOTE: `core::num::<impl int>::checked_add/sub/mul` (and saturating_*) are
            // now recognized total (unconditionally: primitive args, no Drop, Option/
            // clamped return, no user code) — see EXACT_TOTAL + oracle SHOULD_BE_TOTAL.
            "core::char::methods::<impl char>::to_lowercase",
        ] {
            assert!(!total_no_panic_call_summary(callee), "must fail closed: {callee}");
        }
    }

    /// FRONT B note on the ONE entry that left this list. `alloc::string::String::push_str`
    /// was moved OUT (and is asserted total below) after the `Vec::push` audit, on a
    /// DIFFERENT argument from the one that put `Vec::push` back in: `String` carries NO
    /// allocator parameter (`String { vec: Vec<u8> }`, i.e. `Vec<u8, Global>`) and
    /// `push_str(&mut self, &str)` has NO generic parameter at all, so there is no
    /// caller-selected impl it can dispatch into. Its only elided failure is the same
    /// `capacity_overflow()` the crate-wide `Vec::new`/growth abort-only convention already
    /// elides, and it is unreachable without first allocating `> isize::MAX` bytes. The
    /// sibling `String::push` was already accepted and uncontested by this list, so keeping
    /// `push_str` here was stale rather than load-bearing. If the abort-only convention is
    /// ever retired, retire BOTH `String::push` and `String::push_str` together.
    #[test]
    fn callbacks_traits_growth_and_broad_families_fail_closed() {
        assert!(
            total_no_panic_call_summary("alloc::string::String::push_str"),
            "String::push_str stays total under the abort-only convention (no allocator \
             parameter, no generic parameter, no user code) — see the doc comment"
        );
        for callee in [
            "alloc::vec::Vec::<u8>::with_capacity",
            "alloc::vec::Vec::<u8>::shrink_to_fit",
            // `Vec::push` is BACK in this fail-closed list (FRONT B): `Vec` is generic
            // over `A: Allocator`, so its growth path can call caller-selected user code.
            "alloc::vec::Vec::<u8>::push",
            "alloc::vec::Vec::<u8, my_crate::MyAlloc>::push",
            "alloc::string::String::with_capacity",
            "core::str::<impl str>::to_ascii_lowercase",
            "std::ffi::OsStr::to_string_lossy",
            "core::sync::atomic::AtomicU64::load",
            "core::hash::Hasher::write_u64",
            "std::fs::read",
            "std::io::Read::read_to_end",
            "core::convert::From::from",
            "core::convert::Into::into",
            // `checked_add` REMOVED: now recognized total (see EXACT_TOTAL). `wrapping_add`
            // stays fail-closed here — it is modeled by the PRECISE translate_chc
            // wrapping_arith_binop arm, not the flat summary.
            "core::num::<impl u64>::wrapping_add",
            "std::sync::Mutex::<T>::lock",
            "core::mem::zeroed::<T>",
            "core::fmt::Formatter::debug_struct",
            "core::fmt::Display::fmt",
            "core::iter::Iterator::next",
            "core::option::Option::<T>::unwrap_or",
            "core::result::Result::<T, E>::ok",
            "my_crate::core::mem::size_of",
        ] {
            assert!(!total_no_panic_call_summary(callee), "must fail closed: {callee}");
        }
    }

