    // ARGS-FINGERPRINT-READ-1 round 2 (2026-10-07): a PRIMITIVE-argument reader sees
    // past the duplicate-crate-name argument fingerprint through the one shared
    // grammar; a TYPE-PATH reader (`mem::take::<String>`) declines on it, because the
    // tag says an argument's crate name does not identify it. Measured spellings
    // (round-1 review, two same-named `dupty` rlibs linked, preview3-era producer):
    // `core::str::<impl str>::{split::<char>,trim_matches::<char>,contains::<&str>}::<__trust_args@…>`.
    #[test]
    fn test_argument_fingerprint_is_seen_past_only_for_primitive_arguments() {
        let tag = trust_types::render_trailing_args_fingerprint(0x0123_4567_89ab_cdef, 0x42);
        for callee in [
            "core::str::<impl str>::split::<char>",
            "core::str::<impl str>::trim_matches::<char>",
            "core::str::<impl str>::contains::<&str>",
        ] {
            assert!(is_total_str_pattern_method(&format!("{callee}{tag}")), "{callee}");
        }
        assert!(!is_total_str_pattern_method(&format!(
            "core::str::<impl str>::split::<my_crate::MyPattern>{tag}"
        )));
        assert!(is_str_parse_total_primitive_absent_callee(&format!(
            "core::str::<impl str>::parse::<i128>{tag}"
        )));
        assert!(is_str_parse_total_primitive_absent_callee("core::str::<impl str>::parse::<u8>"));
        assert!(!is_str_parse_total_primitive_absent_callee(&format!(
            "core::str::<impl str>::parse::<my::T<u8>>{tag}"
        )));
        // A lookalike is not the tag: the target reads `i128>::<__trust_args`, not
        // a primitive, so the reader declines (fail-closed).
        assert!(!is_str_parse_total_primitive_absent_callee(
            "core::str::<impl str>::parse::<i128>::<__trust_args@0123>"
        ));
        assert!(is_mem_take_total_default_absent_callee(
            "core::mem::take::<alloc::string::String>"
        ));
        assert!(!is_mem_take_total_default_absent_callee(&format!(
            "core::mem::take::<alloc::string::String>{tag}"
        )));
        assert!(!is_mem_take_total_default_absent_callee(&format!(
            "core::mem::take::<alloc::vec::Vec<u8>>{tag}"
        )));
    }

