    /// MUST-NOT (kept fail-closed by construction): the census' panicking index
    /// callees — `<std::vec::Vec<i32> as std::ops::Index<usize>>::index`,
    /// `IndexMut::index_mut`, and the `[u8]` RangeTo `Index::index` — must not be
    /// admitted by ANY of the totality name gates (they genuinely panic OOB; their
    /// obligations must stay). They are `std::ops::` paths, so the `std::iter::`
    /// anchor rejects them outright.
    #[test]
    fn panicking_index_callees_stay_unrecognized() {
        for (callee, method) in [
            ("<std::vec::Vec<i32> as std::ops::Index<usize>>::index", "index"),
            ("<std::vec::Vec<i32> as std::ops::IndexMut<usize>>::index_mut", "index_mut"),
            ("<[u8] as std::ops::Index<std::ops::RangeTo<usize>>>::index", "index"),
        ] {
            assert!(
                !callee_is_std_iter_method(callee, "Iterator", method),
                "{callee} must not pass the std-iterator name gate"
            );
            assert!(
                !callee_is_std_iter_method(callee, "IntoIterator", method),
                "{callee} must not pass the IntoIterator name gate"
            );
            // And the full recognizers decline regardless of receiver.
            assert!(!recognized(ref_to_slice_of(Ty::u32()), None, |args, ctx| {
                total_slice_iterator_call(callee, args, ctx)
            }));
        }
    }

