// ── verified-sysroot §5 step 2b, batch 1: EXACT_TOTAL → bundled body ────────
//
// Two entries left the trusted `EXACT_TOTAL` name list on 2026-08-29:
// `core::num::is_ascii` (u8) and `core::char::methods::is_ascii` (char). Each
// removal replaces a by-name model with the callee's REAL bundled body, and this
// module is the falsification net for both directions of that trade:
//
//   * the model must be GONE (a silent re-add of the summary is the unsound
//     direction — it would grant totality by name again);
//   * with the body IN the bundle the call must BIND to it (no absent-callee
//     row), because that body is now the only discharge the call has;
//   * with the body ABSENT the call must keep the fail-closed
//     `[trust-absent-callee-assumption]` row — removal must never green a call
//     nothing proves;
//   * a body with a REAL unproven hazard under the same name must keep a red
//     row — bundling must never grant totality by name.
#[cfg(test)]
mod exact_total_step2b_batch1_tests {
    use trust_types::{BlockId, SourceSpan, UnwindEdge, VerifiableBody};

    use super::*;

    const U8_IS_ASCII: &str = "core::num::<impl u8>::is_ascii";
    const CHAR_IS_ASCII: &str = "core::char::methods::<impl char>::is_ascii";

    /// The two removed entries fail closed in the summary — in the monomorphized
    /// spelling the extractor renders AND the normalized form the list stores —
    /// while the deliberately-kept siblings still ride the model. If a future
    /// edit re-admits either removed name (or widens a sibling into a family
    /// match that covers it), this is the test that goes red.
    #[test]
    fn removed_is_ascii_entries_fail_closed_in_the_summary() {
        for removed in [
            U8_IS_ASCII,
            "core::num::is_ascii",
            CHAR_IS_ASCII,
            "core::char::methods::is_ascii",
            "std::num::<impl u8>::is_ascii",
            "std::char::methods::<impl char>::is_ascii",
        ] {
            assert!(
                !total_no_panic_call_summary(removed),
                "step-2b removed this entry; the call must be carried by its bundled body, \
                 never a resurrected summary: {removed}"
            );
        }
        // NOT removed in batch 1 or batch 2 — their gate runs have not
        // happened yet. (Batch 2, 2026-08-30, removed the six `u8::is_ascii_*`
        // classifiers and `char::is_ascii_digit` this list originally sampled;
        // its own module pins those. These are the siblings that remain.)
        for kept in [
            "core::num::<impl u8>::is_ascii_alphanumeric",
            "core::num::<impl u8>::is_ascii_punctuation",
            "core::char::methods::<impl char>::is_ascii_alphabetic",
            "core::char::methods::<impl char>::is_ascii_graphic",
        ] {
            assert!(
                total_no_panic_call_summary(kept),
                "sibling must stay modeled until its own step-2b batch: {kept}"
            );
        }
    }

    fn absent_callee_markers(module: &Module) -> usize {
        module
            .proof_obligations
            .iter()
            .filter(|o| {
                o.description.contains(trust_types::assumption::ABSENT_CALLEE_ASSUMPTION_PREFIX)
            })
            .count()
    }

    fn direct_call_edges(module: &Module) -> usize {
        module
            .functions
            .iter()
            .flat_map(|f| f.blocks.iter())
            .flat_map(|b| b.body.iter())
            .filter(|n| matches!(n.inst, Inst::Call { .. }))
            .count()
    }

    /// `u8::is_ascii`'s REAL extracted body (`library/core/src/num/mod.rs:628`,
    /// `*self <= 127`), transcribed from the corpus dump
    /// `trust-clean/fixtures/census-core-m5-2026-07-07/u8-ascii/num__<impl
    /// u8>__is_ascii.json`: deref the `&u8` receiver, one `Le` against `127u8`.
    fn u8_is_ascii_member() -> VerifiableFunction {
        let u8_ty = Ty::Int { width: 8, signed: false };
        VerifiableFunction {
            name: "is_ascii".into(),
            def_path: U8_IS_ASCII.into(),
            span: SourceSpan::default(),
            body: VerifiableBody {
                locals: vec![
                    LocalDecl { index: 0, ty: Ty::Bool, name: None },
                    LocalDecl {
                        index: 1,
                        ty: Ty::Ref { mutable: false, inner: Box::new(u8_ty.clone()) },
                        name: Some("self".into()),
                    },
                    LocalDecl { index: 2, ty: u8_ty, name: None },
                ],
                blocks: vec![TrustBlock {
                    id: BlockId(0),
                    stmts: vec![
                        Statement::Assign {
                            place: Place::local(2),
                            rvalue: Rvalue::Use(Operand::Copy(Place {
                                local: 1,
                                projections: vec![Projection::Deref],
                            })),
                            span: SourceSpan::default(),
                        },
                        Statement::Assign {
                            place: Place::local(0),
                            rvalue: Rvalue::BinaryOp(
                                BinOp::Le,
                                Operand::Move(Place::local(2)),
                                Operand::Constant(ConstValue::Uint(127, 8)),
                            ),
                            span: SourceSpan::default(),
                        },
                    ],
                    terminator: Terminator::Return,
                }],
                arg_count: 1,
                return_ty: Ty::Bool,
                datatype_defs: Default::default(),
            },
            contracts: vec![],
            preconditions: vec![],
            postconditions: vec![],
            spec: Default::default(),
            tuple_layouts: Default::default(),
        }
    }

    /// `char::is_ascii`'s REAL body (`library/core/src/char/methods.rs:1831`,
    /// `*self as u32 <= 0x7F`) in the CURRENT extractor's spelling: the receiver
    /// pointee is `Ty::Char` (the older dumps spelled it `u32`), then an
    /// IntToInt cast to `u32` and one `Le` against `127u32`.
    fn char_is_ascii_member() -> VerifiableFunction {
        let u32_ty = Ty::Int { width: 32, signed: false };
        VerifiableFunction {
            name: "is_ascii".into(),
            def_path: CHAR_IS_ASCII.into(),
            span: SourceSpan::default(),
            body: VerifiableBody {
                locals: vec![
                    LocalDecl { index: 0, ty: Ty::Bool, name: None },
                    LocalDecl {
                        index: 1,
                        ty: Ty::Ref { mutable: false, inner: Box::new(Ty::Char) },
                        name: Some("self".into()),
                    },
                    LocalDecl { index: 2, ty: u32_ty.clone(), name: None },
                    LocalDecl { index: 3, ty: Ty::Char, name: None },
                ],
                blocks: vec![TrustBlock {
                    id: BlockId(0),
                    stmts: vec![
                        Statement::Assign {
                            place: Place::local(3),
                            rvalue: Rvalue::Use(Operand::Copy(Place {
                                local: 1,
                                projections: vec![Projection::Deref],
                            })),
                            span: SourceSpan::default(),
                        },
                        Statement::Assign {
                            place: Place::local(2),
                            rvalue: Rvalue::Cast(Operand::Move(Place::local(3)), u32_ty),
                            span: SourceSpan::default(),
                        },
                        Statement::Assign {
                            place: Place::local(0),
                            rvalue: Rvalue::BinaryOp(
                                BinOp::Le,
                                Operand::Move(Place::local(2)),
                                Operand::Constant(ConstValue::Uint(127, 32)),
                            ),
                            span: SourceSpan::default(),
                        },
                    ],
                    terminator: Terminator::Return,
                }],
                arg_count: 1,
                return_ty: Ty::Bool,
                datatype_defs: Default::default(),
            },
            contracts: vec![],
            preconditions: vec![],
            postconditions: vec![],
            spec: Default::default(),
            tuple_layouts: Default::default(),
        }
    }

    /// A caller `fn(&recv) -> bool` whose single call is `callee_key(arg0)`.
    fn unary_bool_caller(def_path: &str, callee_key: &str, recv_pointee: Ty) -> VerifiableFunction {
        VerifiableFunction {
            name: def_path.rsplit("::").next().unwrap_or(def_path).to_string(),
            def_path: def_path.to_string(),
            span: SourceSpan::default(),
            body: VerifiableBody {
                locals: vec![
                    LocalDecl { index: 0, ty: Ty::Bool, name: None },
                    LocalDecl {
                        index: 1,
                        ty: Ty::Ref { mutable: false, inner: Box::new(recv_pointee) },
                        name: Some("x".into()),
                    },
                ],
                blocks: vec![
                    TrustBlock {
                        id: BlockId(0),
                        stmts: vec![],
                        terminator: Terminator::Call {
                            unwind: UnwindEdge::Unreachable,
                            is_unsafe_sig: false,
                            callee_identity: None,
                            callee_key: None,
                            is_foreign: false,
                            func: callee_key.to_string(),
                            args: vec![Operand::Copy(Place::local(1))],
                            dest: Place::local(0),
                            target: Some(BlockId(1)),
                            span: SourceSpan::default(),
                            atomic: None,
                        },
                    },
                    TrustBlock { id: BlockId(1), stmts: vec![], terminator: Terminator::Return },
                ],
                arg_count: 1,
                return_ty: Ty::Bool,
                datatype_defs: Default::default(),
            },
            contracts: vec![],
            preconditions: vec![],
            postconditions: vec![],
            spec: Default::default(),
            tuple_layouts: Default::default(),
        }
    }

    /// THE DISCHARGE, both entries: with the body IN the bundle the call binds
    /// to it — a real call edge, no absent-callee assumption, and the member
    /// bodies themselves mint no obligation (they have no assert or panic
    /// path). This is the "std body bundled, model replaced" state the step-2b
    /// metric counts.
    #[test]
    fn removed_entries_discharge_against_their_bundled_bodies() {
        let u8_ty = Ty::Int { width: 8, signed: false };
        for (tag, caller_pointee, member) in
            [("u8", u8_ty, u8_is_ascii_member()), ("char", Ty::Char, char_is_ascii_member())]
        {
            let callee = member.def_path.clone();
            let funcs = vec![unary_bool_caller("krate::probe", &callee, caller_pointee), member];
            let module = lower_to_trust_ir_functions("step2b", &funcs)
                .unwrap_or_else(|e| panic!("{tag}: bundle with the real body must lower: {e:?}"));
            assert_eq!(
                absent_callee_markers(&module),
                0,
                "{tag}: the callee IS in the bundle; the call must bind to the body"
            );
            assert_eq!(
                direct_call_edges(&module),
                1,
                "{tag}: a real call edge must be emitted (the old summary emitted none)"
            );
            assert_eq!(
                module.functions.len(),
                2,
                "{tag}: caller and bundled member must both survive lowering"
            );
            step2b_call_boundary_controls::assert_member_called_from_entry(&module);
            // Step-2b metric census (bridge half), labeled per the plan: this is
            // the count of obligations the BRIDGE mints for the caller+body
            // bundle, not a gain estimate and not the compiler-side PF verdict.
            eprintln!(
                "step-2b metric [{tag}]: EXACT_TOTAL entry removed; body bundled; \
                 bridge obligations minted = {} ({:?})",
                module.proof_obligations.len(),
                module.proof_obligations.iter().map(|o| o.description.as_str()).collect::<Vec<_>>()
            );
        }
    }

    /// THE FAIL-CLOSED HALF: the SAME call with the body absent must keep the
    /// honest `[trust-absent-callee-assumption]` row. If any name-based surface
    /// quietly re-covers these callees — the unsound direction of a step-2b
    /// removal — the marker disappears and this test goes red.
    #[test]
    fn removed_entries_without_a_bundled_body_keep_the_absent_callee_row() {
        let u8_ty = Ty::Int { width: 8, signed: false };
        for (tag, caller_pointee, callee) in
            [("u8", u8_ty, U8_IS_ASCII), ("char", Ty::Char, CHAR_IS_ASCII)]
        {
            let funcs = vec![unary_bool_caller("krate::probe", callee, caller_pointee)];
            let module = lower_to_trust_ir_functions("step2b_absent", &funcs)
                .unwrap_or_else(|e| panic!("{tag}: lone caller must still lower: {e:?}"));
            assert_eq!(
                absent_callee_markers(&module),
                1,
                "{tag}: no body and no model — the fail-closed absent-callee row must stand"
            );
            step2b_call_boundary_controls::assert_owned_pending_absent(
                &module,
                module.functions[0].id,
            );
        }
    }

    /// THE MUTANT: a body under the removed u8 name whose content carries a real
    /// unproven hazard (a call to a callee nothing bundles or models). Bundling
    /// binds the caller to this body, and the hazard must SURFACE as a
    /// fail-closed row — if membership of the bundle (or the callee's std-rooted
    /// NAME) ever granted totality regardless of body content, this bundle would
    /// come out clean and this test would go red.
    #[test]
    fn a_bundled_body_with_an_unproven_hazard_stays_red() {
        let mut mutant = u8_is_ascii_member();
        mutant.body.locals.push(LocalDecl { index: 3, ty: Ty::Unit, name: None });
        mutant.body.blocks = vec![
            TrustBlock {
                id: BlockId(0),
                stmts: vec![],
                terminator: Terminator::Call {
                    unwind: UnwindEdge::Unreachable,
                    is_unsafe_sig: false,
                    callee_identity: None,
                    callee_key: None,
                    is_foreign: false,
                    func: "krate::mystery_helper".into(),
                    args: vec![],
                    dest: Place::local(3),
                    target: Some(BlockId(1)),
                    span: SourceSpan::default(),
                    atomic: None,
                },
            },
            TrustBlock {
                id: BlockId(1),
                stmts: vec![Statement::Assign {
                    place: Place::local(0),
                    rvalue: Rvalue::Use(Operand::Constant(ConstValue::Bool(true))),
                    span: SourceSpan::default(),
                }],
                terminator: Terminator::Return,
            },
        ];
        let funcs = vec![
            unary_bool_caller("krate::probe", U8_IS_ASCII, Ty::Int { width: 8, signed: false }),
            mutant,
        ];
        let module = lower_to_trust_ir_functions("step2b_mutant", &funcs)
            .expect("mutant bundle must lower; the hazard is charged, not refused");
        assert!(
            absent_callee_markers(&module) >= 1,
            "the mutant body's unproven call must mint a fail-closed row — bundling must \
             never grant totality by name"
        );
        step2b_call_boundary_controls::assert_reachable_hazard_and_detached_mutant(&module);
    }
}

// ── verified-sysroot §5 step 2b, batch 2: seven more EXACT_TOTAL → body ─────
//
// Batch 2 (2026-08-30) removes the six `u8::is_ascii_*` classifiers whose gate
// run came clean plus `char::is_ascii_digit`. Unlike batch 1 the member bodies
// here are NOT hand-transcribed: each is the REAL monomorphic MIR the composed
// stage1 dumps for the bundled callee (`TRUST_DUMP_MONO=1` +
// `-Ztrust-dump=mir:` over a caller probe; the dump carries the CURRENT
// extractor spelling, e.g. `core::num::<impl u8>::is_ascii_digit`), committed
// under `fixtures/step2b-batch2/` and deserialized here — so the falsification
// net binds the exact bytes the B-lane reads, wrapping-`Sub` range idioms,
// `BitOr` joins, multi-value `SwitchInt` and all. The four directions per
// entry are batch 1's:
//
//   * the by-name model must be GONE (summary fails closed);
//   * with the body IN the bundle the call must BIND to it;
//   * with the body ABSENT the fail-closed absent-callee row must stand;
//   * a same-named body carrying a real unproven hazard must stay red.
#[cfg(test)]
mod exact_total_step2b_batch2_tests {
    use trust_types::{BlockId, SourceSpan, UnwindEdge, VerifiableBody};

    use super::*;

    /// The seven dumped member bodies, keyed by fixture. Each `def_path` inside
    /// the JSON is the current extractor spelling the caller must name.
    const MEMBER_FIXTURES: [(&str, &str); 7] = [
        ("u8_is_ascii_digit", include_str!("../fixtures/step2b-batch2/u8_is_ascii_digit.json")),
        (
            "u8_is_ascii_uppercase",
            include_str!("../fixtures/step2b-batch2/u8_is_ascii_uppercase.json"),
        ),
        (
            "u8_is_ascii_lowercase",
            include_str!("../fixtures/step2b-batch2/u8_is_ascii_lowercase.json"),
        ),
        (
            "u8_is_ascii_alphabetic",
            include_str!("../fixtures/step2b-batch2/u8_is_ascii_alphabetic.json"),
        ),
        (
            "u8_is_ascii_hexdigit",
            include_str!("../fixtures/step2b-batch2/u8_is_ascii_hexdigit.json"),
        ),
        (
            "u8_is_ascii_whitespace",
            include_str!("../fixtures/step2b-batch2/u8_is_ascii_whitespace.json"),
        ),
        ("char_is_ascii_digit", include_str!("../fixtures/step2b-batch2/char_is_ascii_digit.json")),
    ];

    fn member(json: &str) -> VerifiableFunction {
        serde_json::from_str(json).expect("dumped member body must deserialize")
    }

    /// The caller's receiver pointee for a member, read off the member's OWN
    /// `&self` parameter so the probe can never drift from the dumped body.
    fn receiver_pointee(m: &VerifiableFunction) -> Ty {
        let self_decl = m
            .body
            .locals
            .iter()
            .find(|d| d.index == 1)
            .expect("dumped classifier has a receiver local");
        match &self_decl.ty {
            Ty::Ref { inner, .. } => (**inner).clone(),
            other => panic!("classifier receiver must be a shared ref, got {other:?}"),
        }
    }

    fn absent_callee_markers(module: &Module) -> usize {
        module
            .proof_obligations
            .iter()
            .filter(|o| {
                o.description.contains(trust_types::assumption::ABSENT_CALLEE_ASSUMPTION_PREFIX)
            })
            .count()
    }

    fn direct_call_edges(module: &Module) -> usize {
        module
            .functions
            .iter()
            .flat_map(|f| f.blocks.iter())
            .flat_map(|b| b.body.iter())
            .filter(|n| matches!(n.inst, Inst::Call { .. }))
            .count()
    }

    /// A caller `fn(&recv) -> bool` whose single call is `callee_key(arg0)` —
    /// batch 1's probe shape, reused verbatim.
    fn unary_bool_caller(def_path: &str, callee_key: &str, recv_pointee: Ty) -> VerifiableFunction {
        VerifiableFunction {
            name: def_path.rsplit("::").next().unwrap_or(def_path).to_string(),
            def_path: def_path.to_string(),
            span: SourceSpan::default(),
            body: VerifiableBody {
                locals: vec![
                    LocalDecl { index: 0, ty: Ty::Bool, name: None },
                    LocalDecl {
                        index: 1,
                        ty: Ty::Ref { mutable: false, inner: Box::new(recv_pointee) },
                        name: Some("x".into()),
                    },
                ],
                blocks: vec![
                    TrustBlock {
                        id: BlockId(0),
                        stmts: vec![],
                        terminator: Terminator::Call {
                            unwind: UnwindEdge::Unreachable,
                            is_unsafe_sig: false,
                            callee_identity: None,
                            callee_key: None,
                            is_foreign: false,
                            func: callee_key.to_string(),
                            args: vec![Operand::Copy(Place::local(1))],
                            dest: Place::local(0),
                            target: Some(BlockId(1)),
                            span: SourceSpan::default(),
                            atomic: None,
                        },
                    },
                    TrustBlock { id: BlockId(1), stmts: vec![], terminator: Terminator::Return },
                ],
                arg_count: 1,
                return_ty: Ty::Bool,
                datatype_defs: Default::default(),
            },
            contracts: vec![],
            preconditions: vec![],
            postconditions: vec![],
            spec: Default::default(),
            tuple_layouts: Default::default(),
        }
    }

    /// The seven removed entries fail closed in the summary — monomorphized
    /// spelling, normalized spelling, and the `std::` alias — while the
    /// deliberately-kept siblings still ride the model. A future edit that
    /// re-admits any removed name (or widens a sibling into covering one) goes
    /// red here.
    #[test]
    fn removed_batch2_entries_fail_closed_in_the_summary() {
        for removed in [
            "core::num::<impl u8>::is_ascii_digit",
            "core::num::is_ascii_digit",
            "std::num::<impl u8>::is_ascii_digit",
            "core::num::<impl u8>::is_ascii_uppercase",
            "core::num::is_ascii_uppercase",
            "core::num::<impl u8>::is_ascii_lowercase",
            "core::num::is_ascii_lowercase",
            "core::num::<impl u8>::is_ascii_alphabetic",
            "core::num::is_ascii_alphabetic",
            "core::num::<impl u8>::is_ascii_hexdigit",
            "core::num::is_ascii_hexdigit",
            "core::num::<impl u8>::is_ascii_whitespace",
            "core::num::is_ascii_whitespace",
            "core::char::methods::<impl char>::is_ascii_digit",
            "core::char::methods::is_ascii_digit",
            "std::char::methods::<impl char>::is_ascii_digit",
        ] {
            assert!(
                !total_no_panic_call_summary(removed),
                "step-2b batch 2 removed this entry; the call must be carried by its bundled \
                 body, never a resurrected summary: {removed}"
            );
        }
        // NOT removed in this batch — their gate runs have not happened yet.
        for kept in [
            "core::num::<impl u8>::is_ascii_alphanumeric",
            "core::num::<impl u8>::is_ascii_punctuation",
            "core::num::<impl u8>::to_ascii_lowercase",
            "core::char::methods::<impl char>::is_ascii_alphabetic",
            "core::char::methods::<impl char>::is_ascii_whitespace",
        ] {
            assert!(
                total_no_panic_call_summary(kept),
                "sibling must stay modeled until its own step-2b batch: {kept}"
            );
        }
    }

    /// THE DISCHARGE, all seven entries, against the REAL dumped bodies: the
    /// call binds (no absent-callee row), a real call edge exists, and both
    /// functions survive lowering. Prints the step-2b metric triple per entry
    /// (bridge half): entry removed / body bundled / obligations minted.
    #[test]
    fn removed_batch2_entries_discharge_against_their_dumped_bodies() {
        for (tag, json) in MEMBER_FIXTURES {
            let m = member(json);
            let callee = m.def_path.clone();
            let recv = receiver_pointee(&m);
            let funcs = vec![unary_bool_caller("krate::probe", &callee, recv), m];
            let module = lower_to_trust_ir_functions("step2b_b2", &funcs)
                .unwrap_or_else(|e| panic!("{tag}: bundle with the dumped body must lower: {e:?}"));
            assert_eq!(
                absent_callee_markers(&module),
                0,
                "{tag}: the callee IS in the bundle; the call must bind to the dumped body"
            );
            assert_eq!(
                direct_call_edges(&module),
                1,
                "{tag}: a real call edge must be emitted (the old summary emitted none)"
            );
            assert_eq!(
                module.functions.len(),
                2,
                "{tag}: caller and bundled member must both survive lowering"
            );
            step2b_call_boundary_controls::assert_member_called_from_entry(&module);
            eprintln!(
                "step-2b metric [batch2/{tag}]: EXACT_TOTAL entry removed; body bundled; \
                 bridge obligations minted = {} ({:?})",
                module.proof_obligations.len(),
                module.proof_obligations.iter().map(|o| o.description.as_str()).collect::<Vec<_>>()
            );
        }
    }

    /// THE FAIL-CLOSED HALF: the same call with the body absent keeps the
    /// honest `[trust-absent-callee-assumption]` row, for every entry.
    #[test]
    fn removed_batch2_entries_without_a_bundled_body_keep_the_absent_callee_row() {
        for (tag, json) in MEMBER_FIXTURES {
            let m = member(json);
            let funcs = vec![unary_bool_caller("krate::probe", &m.def_path, receiver_pointee(&m))];
            let module = lower_to_trust_ir_functions("step2b_b2_absent", &funcs)
                .unwrap_or_else(|e| panic!("{tag}: lone caller must still lower: {e:?}"));
            assert_eq!(
                absent_callee_markers(&module),
                1,
                "{tag}: no body and no model — the fail-closed absent-callee row must stand"
            );
            step2b_call_boundary_controls::assert_owned_pending_absent(
                &module,
                module.functions[0].id,
            );
        }
    }

    /// THE MUTANT: a body under a removed batch-2 name whose content carries a
    /// real unproven hazard must keep a red row — bundling never grants
    /// totality by name. One entry suffices (the mechanism is name-independent
    /// and batch 1 pins it for its own names); the u8 classifier shape is used.
    #[test]
    fn a_batch2_bundled_body_with_an_unproven_hazard_stays_red() {
        let mut mutant = member(MEMBER_FIXTURES[0].1);
        let recv = receiver_pointee(&mutant);
        mutant.body.locals.push(LocalDecl {
            index: mutant.body.locals.len(),
            ty: Ty::Unit,
            name: None,
        });
        let hazard_dest = mutant.body.locals.len() - 1;
        mutant.body.blocks = vec![
            TrustBlock {
                id: BlockId(0),
                stmts: vec![],
                terminator: Terminator::Call {
                    unwind: UnwindEdge::Unreachable,
                    is_unsafe_sig: false,
                    callee_identity: None,
                    callee_key: None,
                    is_foreign: false,
                    func: "krate::mystery_helper".into(),
                    args: vec![],
                    dest: Place::local(hazard_dest),
                    target: Some(BlockId(1)),
                    span: SourceSpan::default(),
                    atomic: None,
                },
            },
            TrustBlock {
                id: BlockId(1),
                stmts: vec![Statement::Assign {
                    place: Place::local(0),
                    rvalue: Rvalue::Use(Operand::Constant(ConstValue::Bool(true))),
                    span: SourceSpan::default(),
                }],
                terminator: Terminator::Return,
            },
        ];
        let callee = mutant.def_path.clone();
        let funcs = vec![unary_bool_caller("krate::probe", &callee, recv), mutant];
        let module = lower_to_trust_ir_functions("step2b_b2_mutant", &funcs)
            .expect("mutant bundle must lower; the hazard is charged, not refused");
        assert!(
            absent_callee_markers(&module) >= 1,
            "the mutant body's unproven call must mint a fail-closed row — bundling must \
             never grant totality by name"
        );
        step2b_call_boundary_controls::assert_reachable_hazard_and_detached_mutant(&module);
    }
}

#[cfg(test)]
mod bundled_member_assert_admission_tests {
    use trust_types::{FunctionSpec, SourceSpan, UnwindEdge, VerifiableBody, VerifiableFunction};

    use super::*;

    fn local(index: usize, ty: Ty, name: Option<&str>) -> LocalDecl {
        LocalDecl { index, ty, name: name.map(str::to_string) }
    }

    fn assign_binary(dest: usize, op: BinOp, lhs: usize, rhs: usize) -> Statement {
        Statement::Assign {
            place: Place::local(dest),
            rvalue: Rvalue::BinaryOp(
                op,
                Operand::Copy(Place::local(lhs)),
                Operand::Copy(Place::local(rhs)),
            ),
            span: SourceSpan::default(),
        }
    }

    fn assertion(msg: AssertMessage, target: usize) -> Terminator {
        Terminator::Assert {
            cond: Operand::Copy(Place::local(3)),
            expected: false,
            msg,
            target: BlockId(target),
            unwind: UnwindEdge::Unreachable,
            span: SourceSpan::default(),
        }
    }

    fn function(blocks: Vec<TrustBlock>) -> VerifiableFunction {
        VerifiableFunction {
            name: "member".into(),
            def_path: "test::member".into(),
            span: SourceSpan::default(),
            body: VerifiableBody {
                locals: vec![
                    local(0, Ty::u8(), Some("ret")),
                    local(1, Ty::u8(), Some("lhs")),
                    local(2, Ty::u8(), Some("rhs")),
                    local(3, Ty::Bool, Some("is_zero")),
                    local(4, Ty::u8(), Some("quotient")),
                    local(5, Ty::u8(), Some("other")),
                ],
                blocks,
                arg_count: 2,
                return_ty: Ty::u8(),
                datatype_defs: Default::default(),
            },
            contracts: vec![],
            preconditions: vec![],
            postconditions: vec![],
            spec: FunctionSpec::default(),
            tuple_layouts: Default::default(),
        }
    }

    fn exact_div_member() -> VerifiableFunction {
        function(vec![
            TrustBlock {
                id: BlockId(0),
                stmts: vec![],
                terminator: assertion(AssertMessage::DivisionByZero, 1),
            },
            TrustBlock {
                id: BlockId(1),
                stmts: vec![assign_binary(4, BinOp::Div, 1, 2)],
                terminator: Terminator::Return,
            },
        ])
    }

    #[test]
    fn no_assert_is_distinct_from_refusal() {
        let member = function(vec![TrustBlock {
            id: BlockId(0),
            stmts: vec![],
            terminator: Terminator::Return,
        }]);
        assert_eq!(
            bundled_member_assert_admission(&member),
            BundledMemberAssertAdmission::NoAsserts
        );
    }

    #[test]
    fn exact_entry_div_assert_derives_one_formal_rooted_charge() {
        let member = exact_div_member();
        let BundledMemberAssertAdmission::Derived { param_names, requires } =
            bundled_member_assert_admission(&member)
        else {
            panic!("the exact direct Div shape must be admitted");
        };
        assert_eq!(param_names, ["lhs", "rhs"]);
        assert_eq!(
            requires,
            [Formula::Not(Box::new(Formula::Eq(
                Box::new(Formula::var("rhs", Sort::Int)),
                Box::new(Formula::Int(0)),
            )))]
        );
    }

    #[test]
    fn guarded_assert_refuses_the_whole_member() {
        let member = function(vec![
            TrustBlock {
                id: BlockId(0),
                stmts: vec![],
                terminator: Terminator::SwitchInt {
                    discr: Operand::Copy(Place::local(3)),
                    targets: vec![(1, BlockId(1))],
                    otherwise: BlockId(3),
                    exhaustive_enum_unreachable: false,
                    span: SourceSpan::default(),
                },
            },
            TrustBlock {
                id: BlockId(1),
                stmts: vec![],
                terminator: assertion(AssertMessage::DivisionByZero, 2),
            },
            TrustBlock {
                id: BlockId(2),
                stmts: vec![assign_binary(4, BinOp::Div, 1, 2)],
                terminator: Terminator::Return,
            },
            TrustBlock { id: BlockId(3), stmts: vec![], terminator: Terminator::Return },
        ]);
        assert!(matches!(
            bundled_member_assert_admission(&member),
            BundledMemberAssertAdmission::Refused {
                reason: "member has a guarded or non-entry-prefix Assert",
                class: MemberAssertRefusalClass::GuardedOrNonEntryPrefix,
            }
        ));
    }

    /// Trust (2026-10-01): `rhs = 0` on a loop body, then back into the prefix.
    fn zero_rhs_then_goto(target: usize) -> TrustBlock {
        TrustBlock {
            id: BlockId(9),
            stmts: vec![Statement::Assign {
                place: Place::local(2),
                rvalue: Rvalue::Use(Operand::Constant(ConstValue::Uint(0, 8))),
                span: SourceSpan::default(),
            }],
            terminator: Terminator::Goto(BlockId(target)),
        }
    }

    fn switch_on_quotient(zero: usize, otherwise: usize) -> Terminator {
        Terminator::SwitchInt {
            discr: Operand::Copy(Place::local(4)),
            targets: vec![(0, BlockId(zero))],
            otherwise: BlockId(otherwise),
            exhaustive_enum_unreachable: false,
            span: SourceSpan::default(),
        }
    }

    /// Trust (2026-10-01): the charge `rhs != 0` names the divisor's ENTRY value,
    /// so it covers an Assert that runs once from the entry. A loop body that
    /// zeroes `rhs` and jumps back to the Assert block makes the second pass
    /// divide by zero under a charge the caller met: the re-entered block is cut
    /// from the prefix and its Assert refuses as the guarded/non-entry gap.
    #[test]
    fn a_loop_back_into_the_assert_block_refuses_the_divisor_charge() {
        let looped = |back_edge: bool| {
            function(vec![
                TrustBlock {
                    id: BlockId(0),
                    stmts: vec![],
                    terminator: Terminator::Goto(BlockId(1)),
                },
                TrustBlock {
                    id: BlockId(1),
                    stmts: vec![],
                    terminator: assertion(AssertMessage::DivisionByZero, 2),
                },
                TrustBlock {
                    id: BlockId(2),
                    stmts: vec![assign_binary(4, BinOp::Div, 1, 2)],
                    terminator: switch_on_quotient(3, 9),
                },
                TrustBlock { id: BlockId(3), stmts: vec![], terminator: Terminator::Return },
                zero_rhs_then_goto(if back_edge { 1 } else { 3 }),
            ])
        };
        assert!(matches!(
            bundled_member_assert_admission(&looped(false)),
            BundledMemberAssertAdmission::Derived { ref requires, .. } if requires.len() == 1
        ));
        assert!(matches!(
            bundled_member_assert_admission(&looped(true)),
            BundledMemberAssertAdmission::Refused {
                reason: "member has a guarded or non-entry-prefix Assert",
                class: MemberAssertRefusalClass::GuardedOrNonEntryPrefix,
            }
        ));
    }

    /// Trust (2026-10-01): a back edge into the ENTRY block itself leaves no
    /// single-entry prefix at all.
    #[test]
    fn a_loop_back_into_the_entry_block_refuses() {
        let member = function(vec![
            TrustBlock {
                id: BlockId(0),
                stmts: vec![],
                terminator: assertion(AssertMessage::DivisionByZero, 1),
            },
            TrustBlock {
                id: BlockId(1),
                stmts: vec![assign_binary(4, BinOp::Div, 1, 2)],
                terminator: switch_on_quotient(2, 9),
            },
            TrustBlock { id: BlockId(2), stmts: vec![], terminator: Terminator::Return },
            zero_rhs_then_goto(0),
        ]);
        assert!(matches!(
            bundled_member_assert_admission(&member),
            BundledMemberAssertAdmission::Refused {
                reason: "member has a guarded or non-entry-prefix Assert",
                class: MemberAssertRefusalClass::GuardedOrNonEntryPrefix,
            }
        ));
    }

    /// Trust (2026-10-01): the Assert runs once, but the operation it is matched
    /// to sits in a block a back edge re-enters, where the divisor read is not the
    /// prefix's. Refused as the completeness gap, not as an integrity failure.
    #[test]
    fn an_assert_whose_target_is_re_entered_refuses() {
        let member = function(vec![
            TrustBlock {
                id: BlockId(0),
                stmts: vec![],
                terminator: assertion(AssertMessage::DivisionByZero, 1),
            },
            TrustBlock {
                id: BlockId(1),
                stmts: vec![assign_binary(4, BinOp::Div, 1, 2)],
                terminator: switch_on_quotient(2, 9),
            },
            TrustBlock { id: BlockId(2), stmts: vec![], terminator: Terminator::Return },
            zero_rhs_then_goto(1),
        ]);
        assert!(matches!(
            bundled_member_assert_admission(&member),
            BundledMemberAssertAdmission::Refused {
                reason: "member Assert target is re-entered by another edge, off the single-entry prefix",
                class: MemberAssertRefusalClass::GuardedOrNonEntryPrefix,
            }
        ));
    }

    /// Trust (BoundsCheck lane): `AssertMessage::BoundsCheck` moved INTO the
    /// lane, so this test now uses an arithmetic-overflow Assert — still a kind
    /// with no exact caller-side charge, and still the property that matters: an
    /// unrecognized Assert REFUSES the member rather than vanishing from it.
    #[test]
    fn non_div_rem_assert_refuses_instead_of_disappearing() {
        let member = function(vec![
            TrustBlock {
                id: BlockId(0),
                stmts: vec![],
                terminator: assertion(AssertMessage::Overflow(BinOp::Add), 1),
            },
            TrustBlock { id: BlockId(1), stmts: vec![], terminator: Terminator::Return },
        ]);
        assert!(matches!(
            bundled_member_assert_admission(&member),
            BundledMemberAssertAdmission::Refused {
                reason: "member Assert kind `Overflow(Add)` is outside the exact Div/Rem/BoundsCheck lane",
                class: MemberAssertRefusalClass::AssertKindOutsideLane,
            }
        ));
    }

    #[test]
    fn two_same_ops_at_one_assert_target_are_ambiguous_and_refused() {
        let member = function(vec![
            TrustBlock {
                id: BlockId(0),
                stmts: vec![],
                terminator: assertion(AssertMessage::DivisionByZero, 1),
            },
            TrustBlock {
                id: BlockId(1),
                stmts: vec![assign_binary(4, BinOp::Div, 1, 2), assign_binary(5, BinOp::Div, 1, 1)],
                terminator: Terminator::Return,
            },
        ]);
        assert!(matches!(
            bundled_member_assert_admission(&member),
            BundledMemberAssertAdmission::Refused {
                reason: "member Assert does not correspond to exactly one matching operation",
                class: MemberAssertRefusalClass::UnpairedOperation,
            }
        ));
    }

    fn assign_binary_const_rhs(dest: usize, op: BinOp, lhs: usize, rhs: ConstValue) -> Statement {
        Statement::Assign {
            place: Place::local(dest),
            rvalue: Rvalue::BinaryOp(op, Operand::Copy(Place::local(lhs)), Operand::Constant(rhs)),
            span: SourceSpan::default(),
        }
    }

    /// `x / 4` — the `trait_panic_free_impl_discharges.rs` shape. A NONZERO
    /// integer-constant divisor discharges its own Assert: the member is
    /// admitted with NO caller-side charge. Refusing it as "not formal-rooted"
    /// was the over-refusal that regressed that fixture (90f22093e9).
    #[test]
    fn nonzero_constant_divisor_discharges_its_own_assert() {
        let member = function(vec![
            TrustBlock {
                id: BlockId(0),
                stmts: vec![],
                terminator: assertion(AssertMessage::DivisionByZero, 1),
            },
            TrustBlock {
                id: BlockId(1),
                stmts: vec![assign_binary_const_rhs(4, BinOp::Div, 1, ConstValue::Uint(4, 8))],
                terminator: Terminator::Return,
            },
        ]);
        assert_eq!(
            bundled_member_assert_admission(&member),
            BundledMemberAssertAdmission::Derived {
                param_names: vec!["lhs".into(), "rhs".into()],
                requires: vec![],
            }
        );
        // The derived-summary lane treats an all-discharged member exactly
        // like a `NoAsserts` one: nothing to register.
        assert_eq!(member_entry_prefix_assert_requires(&member), None);
    }

    /// A ZERO constant divisor is a guaranteed panic. It must never be
    /// self-discharged — the falsifying direction of the const lane.
    #[test]
    fn zero_constant_divisor_refuses_the_member() {
        let member = function(vec![
            TrustBlock {
                id: BlockId(0),
                stmts: vec![],
                terminator: assertion(AssertMessage::DivisionByZero, 1),
            },
            TrustBlock {
                id: BlockId(1),
                stmts: vec![assign_binary_const_rhs(4, BinOp::Div, 1, ConstValue::Uint(0, 8))],
                terminator: Terminator::Return,
            },
        ]);
        assert_eq!(
            bundled_member_assert_admission(&member),
            BundledMemberAssertAdmission::Refused {
                reason: "member Assert divisor is a constant that is zero or not an auditable integer",
                class: MemberAssertRefusalClass::Other,
            }
        );
    }

    /// The chained spelling `_5 = const 8; _4 = _1 % _5` resolves through the
    /// single straight-line definition to the same nonzero constant and
    /// discharges identically.
    #[test]
    fn chained_use_of_a_nonzero_constant_divisor_discharges() {
        let member = function(vec![
            TrustBlock {
                id: BlockId(0),
                stmts: vec![Statement::Assign {
                    place: Place::local(5),
                    rvalue: Rvalue::Use(Operand::Constant(ConstValue::Uint(8, 8))),
                    span: SourceSpan::default(),
                }],
                terminator: assertion(AssertMessage::RemainderByZero, 1),
            },
            TrustBlock {
                id: BlockId(1),
                stmts: vec![assign_binary(4, BinOp::Rem, 1, 5)],
                terminator: Terminator::Return,
            },
        ]);
        assert_eq!(
            bundled_member_assert_admission(&member),
            BundledMemberAssertAdmission::Derived {
                param_names: vec!["lhs".into(), "rhs".into()],
                requires: vec![],
            }
        );
    }

    /// A mixed member: one formal-rooted charge plus one self-discharged
    /// constant check. Exactly the formal charge survives, and the accounting
    /// still covers BOTH asserts (neither is silently dropped).
    #[test]
    fn mixed_formal_and_constant_divisors_charge_only_the_formal() {
        let member = function(vec![
            TrustBlock {
                id: BlockId(0),
                stmts: vec![],
                terminator: assertion(AssertMessage::DivisionByZero, 1),
            },
            TrustBlock {
                id: BlockId(1),
                stmts: vec![assign_binary(4, BinOp::Div, 1, 2)],
                terminator: assertion(AssertMessage::RemainderByZero, 2),
            },
            TrustBlock {
                id: BlockId(2),
                stmts: vec![assign_binary_const_rhs(5, BinOp::Rem, 1, ConstValue::Uint(16, 8))],
                terminator: Terminator::Return,
            },
        ]);
        assert_eq!(
            bundled_member_assert_admission(&member),
            BundledMemberAssertAdmission::Derived {
                param_names: vec!["lhs".into(), "rhs".into()],
                requires: vec![Formula::Not(Box::new(Formula::Eq(
                    Box::new(Formula::var("rhs", Sort::Int)),
                    Box::new(Formula::Int(0)),
                )))],
            }
        );
    }

    // Trust (2026-09-29): the refusal CLASS is what the compiler's bundled
    // std-member disposition reads (`MemberAssertRefusalClass`). The two tolerable
    // classes are pinned above (`guarded_assert_refuses_the_whole_member`,
    // `non_div_rem_assert_refuses_instead_of_disappearing`); these pin that an
    // integrity or shape refusal is `Other` — never tolerable — even when the
    // member also carries an Assert of a tolerable kind.

    /// A nullary member has no formal to charge: `Other`, whatever its Assert.
    #[test]
    fn an_assert_bearing_nullary_member_is_class_other() {
        let mut member = function(vec![
            TrustBlock {
                id: BlockId(0),
                stmts: vec![],
                terminator: assertion(AssertMessage::Overflow(BinOp::Add), 1),
            },
            TrustBlock { id: BlockId(1), stmts: vec![], terminator: Terminator::Return },
        ]);
        member.body.arg_count = 0;
        assert_eq!(
            bundled_member_assert_admission(&member),
            BundledMemberAssertAdmission::Refused {
                reason: "assert-bearing member has no formal parameter to charge",
                class: MemberAssertRefusalClass::Other,
            }
        );
    }

    /// A Div Assert whose success edge names a block the body does not have is an
    /// integrity failure, not a completeness gap: `Other`. The entry-prefix walk
    /// declines the dangling edge first, with its own `Other` reason.
    #[test]
    fn a_missing_success_target_is_class_other() {
        let member = function(vec![TrustBlock {
            id: BlockId(0),
            stmts: vec![assign_binary(4, BinOp::Div, 1, 2)],
            terminator: assertion(AssertMessage::DivisionByZero, 9),
        }]);
        let BundledMemberAssertAdmission::Refused { class, .. } =
            bundled_member_assert_admission(&member)
        else {
            panic!("a dangling Assert target must refuse the member");
        };
        assert_eq!(class, MemberAssertRefusalClass::Other);
    }

    /// An entry-prefix Div refused for its SHAPE (two matching operations) before
    /// a later Overflow Assert: the first refusal decides, and it is `Other`. The
    /// tolerable kind further down cannot launder the integrity refusal.
    #[test]
    fn an_integrity_refusal_before_a_kind_refusal_stays_class_other() {
        let member = function(vec![
            TrustBlock {
                id: BlockId(0),
                stmts: vec![],
                terminator: assertion(AssertMessage::DivisionByZero, 1),
            },
            TrustBlock {
                id: BlockId(1),
                stmts: vec![assign_binary(4, BinOp::Div, 1, 2), assign_binary(5, BinOp::Div, 1, 1)],
                terminator: assertion(AssertMessage::Overflow(BinOp::Add), 2),
            },
            TrustBlock { id: BlockId(2), stmts: vec![], terminator: Terminator::Return },
        ]);
        assert_eq!(
            bundled_member_assert_admission(&member),
            BundledMemberAssertAdmission::Refused {
                reason: "member Assert does not correspond to exactly one matching operation",
                class: MemberAssertRefusalClass::UnpairedOperation,
            }
        );
    }
}

#[cfg(test)]
mod bundled_member_bounds_check_admission_tests {
    //! The BoundsCheck half of [`bundled_member_assert_admission`].
    //!
    //! # Why this lane exists
    //!
    //! `ensure_bundled_member_asserts_exactly_charged` (the compiler's
    //! bundled-member Assert authority gate) refuses a whole proof-authority
    //! bundle unless every FOREIGN Assert-bearing member carries an exact
    //! caller-side charge, because the bridge's private per-member obligations
    //! are cleared at the public-inventory boundary. Before this lane the
    //! derivation covered only `DivisionByZero`/`RemainderByZero`, so a
    //! `Vec`/slice index — whose Assert is a `BoundsCheck` inside
    //! `<usize as SliceIndex<[T]>>::index` — refused, and the refusal aborted
    //! the compilation before ANY obligation was reported.
    //!
    //! # The shape being charged
    //!
    //! rustc lowers an in-bounds check to
    //!
    //! ```text
    //! _len  = PtrMetadata(<slice formal>)
    //! _cond = Lt(<index>, _len)
    //! Assert(_cond, expected: true, BoundsCheck) -> <success>
    //! ```
    //!
    //! and the derived charge is `index < <slice formal>__slice_len`. The
    //! `__slice_len` spelling is not decoration: `trust_vcgen`'s call-site
    //! producer substitutes it from the ACTUAL's own length, which is what makes
    //! the charge land on the caller rather than on a free variable.
    //!
    //! # What must never be weakened
    //!
    //! Every refusal below is a shape whose charge cannot be derived EXACTLY.
    //! Admitting any of them would charge a caller a proposition about a
    //! quantity the Assert does not compare — which is worse than the refusal,
    //! because a refusal fails the build while a wrong charge greens it.

    use trust_types::{FunctionSpec, SourceSpan, UnwindEdge, VerifiableBody, VerifiableFunction};

    use super::*;

    const INDEX: usize = 1;
    const SLICE: usize = 2;
    const LEN: usize = 3;
    const COND: usize = 4;

    fn local(index: usize, ty: Ty, name: Option<&str>) -> LocalDecl {
        LocalDecl { index, ty, name: name.map(str::to_string) }
    }

    fn slice_ref_i32() -> Ty {
        Ty::Ref { mutable: false, inner: Box::new(Ty::Slice { elem: Box::new(Ty::i32()) }) }
    }

    /// `_LEN = PtrMetadata(copy _source)`.
    fn assign_ptr_metadata(dest: usize, source: usize) -> Statement {
        Statement::Assign {
            place: Place::local(dest),
            rvalue: Rvalue::UnaryOp(UnOp::PtrMetadata, Operand::Copy(Place::local(source))),
            span: SourceSpan::default(),
        }
    }

    /// `_COND = Lt(copy _lhs, copy _rhs)`.
    fn assign_lt(dest: usize, lhs: usize, rhs: usize) -> Statement {
        Statement::Assign {
            place: Place::local(dest),
            rvalue: Rvalue::BinaryOp(
                BinOp::Lt,
                Operand::Copy(Place::local(lhs)),
                Operand::Copy(Place::local(rhs)),
            ),
            span: SourceSpan::default(),
        }
    }

    fn bounds_assert(cond_local: usize, expected: bool, target: usize) -> Terminator {
        Terminator::Assert {
            cond: Operand::Move(Place::local(cond_local)),
            expected,
            msg: AssertMessage::BoundsCheck,
            target: BlockId(target),
            unwind: UnwindEdge::Continue,
            span: SourceSpan::default(),
        }
    }

    /// The `<usize as SliceIndex<[i32]>>::index` local/signature layout, so the
    /// mutants below differ from the admitted shape in exactly one respect.
    fn member(slice_ty: Ty, blocks: Vec<TrustBlock>) -> VerifiableFunction {
        VerifiableFunction {
            name: "index".into(),
            def_path: "<usize as core::slice::index::SliceIndex<[i32]>>::index".into(),
            span: SourceSpan::default(),
            body: VerifiableBody {
                locals: vec![
                    local(0, Ty::Ref { mutable: false, inner: Box::new(Ty::i32()) }, None),
                    local(INDEX, Ty::usize(), Some("self")),
                    local(SLICE, slice_ty, Some("slice")),
                    local(LEN, Ty::usize(), None),
                    local(COND, Ty::Bool, None),
                ],
                blocks,
                arg_count: 2,
                return_ty: Ty::Ref { mutable: false, inner: Box::new(Ty::i32()) },
                datatype_defs: Default::default(),
            },
            contracts: vec![],
            preconditions: vec![],
            postconditions: vec![],
            spec: FunctionSpec::default(),
            tuple_layouts: Default::default(),
        }
    }

    fn exact_bounds_member() -> VerifiableFunction {
        member(
            slice_ref_i32(),
            vec![
                TrustBlock {
                    id: BlockId(0),
                    stmts: vec![assign_ptr_metadata(LEN, SLICE), assign_lt(COND, INDEX, LEN)],
                    terminator: bounds_assert(COND, true, 1),
                },
                TrustBlock { id: BlockId(1), stmts: vec![], terminator: Terminator::Return },
            ],
        )
    }

    fn expected_charge() -> Formula {
        Formula::Lt(
            Box::new(Formula::var("self", Sort::Int)),
            Box::new(Formula::var("slice__slice_len", Sort::Int)),
        )
    }

    #[test]
    fn exact_entry_bounds_assert_derives_the_index_lt_length_charge() {
        let BundledMemberAssertAdmission::Derived { param_names, requires } =
            bundled_member_assert_admission(&exact_bounds_member())
        else {
            panic!("the exact entry-prefix BoundsCheck shape must be admitted");
        };
        assert_eq!(param_names, ["self", "slice"]);
        assert_eq!(requires, [expected_charge()]);
    }

    /// The derived-summary entry point must expose the same charge — this is the
    /// accessor the summary lane registers, and a `None` here would mean the
    /// Assert is accounted as if the member owed its callers nothing.
    #[test]
    fn the_derived_summary_lane_publishes_the_bounds_charge() {
        let (param_names, requires) = member_entry_prefix_assert_requires(&exact_bounds_member())
            .expect("an admitted bounds member owes its callers a charge");
        assert_eq!(param_names, ["self", "slice"]);
        assert_eq!(requires, [expected_charge()]);
    }

    /// A `&mut [T]` formal carries the same pointer metadata; the write path
    /// (`IndexMut::index_mut`) must charge identically to the read path.
    #[test]
    fn a_mutable_slice_formal_charges_identically() {
        let mutable =
            Ty::Ref { mutable: true, inner: Box::new(Ty::Slice { elem: Box::new(Ty::i32()) }) };
        let member = member(
            mutable,
            vec![
                TrustBlock {
                    id: BlockId(0),
                    stmts: vec![assign_ptr_metadata(LEN, SLICE), assign_lt(COND, INDEX, LEN)],
                    terminator: bounds_assert(COND, true, 1),
                },
                TrustBlock { id: BlockId(1), stmts: vec![], terminator: Terminator::Return },
            ],
        );
        let BundledMemberAssertAdmission::Derived { requires, .. } =
            bundled_member_assert_admission(&member)
        else {
            panic!("a `&mut [T]` bounds member must be admitted");
        };
        assert_eq!(requires, [expected_charge()]);
    }

    /// `PtrMetadata` is a LENGTH only for a runtime slice. For a `&str` it is a
    /// byte count and for a `&dyn Trait` a vtable pointer — charging
    /// `index < <that>` would be a proposition about the wrong quantity. The
    /// decision is taken from the formal's rustc-extracted `Ty`, so this mutant
    /// changes ONLY that type.
    #[test]
    fn pointer_metadata_of_a_non_slice_formal_refuses() {
        let member = member(
            Ty::Ref { mutable: false, inner: Box::new(Ty::Str) },
            vec![
                TrustBlock {
                    id: BlockId(0),
                    stmts: vec![assign_ptr_metadata(LEN, SLICE), assign_lt(COND, INDEX, LEN)],
                    terminator: bounds_assert(COND, true, 1),
                },
                TrustBlock { id: BlockId(1), stmts: vec![], terminator: Terminator::Return },
            ],
        );
        assert_eq!(
            bundled_member_assert_admission(&member),
            BundledMemberAssertAdmission::Refused {
                reason: "member BoundsCheck bound is not the pointer metadata of a slice formal",
                class: MemberAssertRefusalClass::Other,
            }
        );
    }

    /// A bound that is some other in-body temp — not the metadata of a formal —
    /// has no `<formal>__slice_len` spelling for the call-site producer to
    /// rebind, so charging it would leave a free variable in the caller's VC.
    #[test]
    fn a_bound_that_is_not_formal_metadata_refuses() {
        let mut member = exact_bounds_member();
        member.body.locals.push(local(5, Ty::usize(), None));
        member.body.blocks[0].stmts = vec![
            Statement::Assign {
                place: Place::local(5),
                rvalue: Rvalue::Use(Operand::Constant(ConstValue::Uint(8, 64))),
                span: SourceSpan::default(),
            },
            assign_lt(COND, INDEX, 5),
        ];
        assert_eq!(
            bundled_member_assert_admission(&member),
            BundledMemberAssertAdmission::Refused {
                reason: "member BoundsCheck bound is not the pointer metadata of a slice formal",
                class: MemberAssertRefusalClass::Other,
            }
        );
    }

    /// An index that is not uniquely formal-rooted cannot be named in the
    /// caller's namespace at all.
    #[test]
    fn a_non_formal_rooted_index_refuses() {
        let mut member = exact_bounds_member();
        member.body.locals.push(local(5, Ty::usize(), None));
        member.body.blocks[0].stmts = vec![
            assign_ptr_metadata(LEN, SLICE),
            // `_5` has no definition at all: nothing roots it in a formal.
            assign_lt(COND, 5, LEN),
        ];
        assert_eq!(
            bundled_member_assert_admission(&member),
            BundledMemberAssertAdmission::Refused {
                reason: "member BoundsCheck index is not uniquely formal-rooted",
                class: MemberAssertRefusalClass::UnrootedOperand,
            }
        );
    }

    /// `expected: false` asserts the NEGATION of the comparison — a different
    /// proposition, and not the shape rustc emits for an in-bounds check.
    #[test]
    fn an_assert_of_the_negated_comparison_refuses() {
        let mut member = exact_bounds_member();
        member.body.blocks[0].terminator = bounds_assert(COND, false, 1);
        assert_eq!(
            bundled_member_assert_admission(&member),
            BundledMemberAssertAdmission::Refused {
                reason: "member BoundsCheck Assert does not assert its comparison true",
                class: MemberAssertRefusalClass::Other,
            }
        );
    }

    /// The Assert must read the very comparison being charged. Here the sole
    /// `Lt` in the prefix is a DIFFERENT comparison that the Assert never looks
    /// at, so uniqueness alone would have charged the wrong one.
    #[test]
    fn an_assert_reading_an_unrelated_condition_refuses() {
        let mut member = exact_bounds_member();
        member.body.locals.push(local(5, Ty::Bool, None));
        member.body.blocks[0].terminator = bounds_assert(5, true, 1);
        assert_eq!(
            bundled_member_assert_admission(&member),
            BundledMemberAssertAdmission::Refused {
                reason: "member BoundsCheck Assert condition is not the matching comparison",
                class: MemberAssertRefusalClass::Other,
            }
        );
    }

    /// Two `Lt` comparisons in the charged region: the correspondence is
    /// ambiguous and the member refuses, exactly as the Div/Rem lane does.
    #[test]
    fn two_comparisons_at_one_bounds_assert_are_ambiguous_and_refused() {
        let mut member = exact_bounds_member();
        member.body.locals.push(local(5, Ty::Bool, None));
        member.body.blocks[0].stmts.push(assign_lt(5, LEN, INDEX));
        assert_eq!(
            bundled_member_assert_admission(&member),
            BundledMemberAssertAdmission::Refused {
                reason: "member Assert does not correspond to exactly one matching operation",
                class: MemberAssertRefusalClass::UnpairedOperation,
            }
        );
    }

    /// A metadata temp written TWICE has no single definition to charge from.
    #[test]
    fn a_twice_defined_length_temp_refuses() {
        let mut member = exact_bounds_member();
        member.body.blocks[0].stmts = vec![
            assign_ptr_metadata(LEN, SLICE),
            assign_ptr_metadata(LEN, SLICE),
            assign_lt(COND, INDEX, LEN),
        ];
        assert_eq!(
            bundled_member_assert_admission(&member),
            BundledMemberAssertAdmission::Refused {
                reason: "member BoundsCheck bound is not the pointer metadata of a slice formal",
                class: MemberAssertRefusalClass::Other,
            }
        );
    }

    /// A BoundsCheck reached only through a branch is GUARDED: the derived
    /// requires would charge a caller unconditionally for a check the member
    /// only sometimes performs. The whole member refuses — never the visible
    /// subset.
    #[test]
    fn a_guarded_bounds_assert_refuses_the_whole_member() {
        let mut member = exact_bounds_member();
        member.body.locals.push(local(5, Ty::Bool, None));
        member.body.blocks = vec![
            TrustBlock {
                id: BlockId(0),
                stmts: vec![],
                terminator: Terminator::SwitchInt {
                    discr: Operand::Copy(Place::local(5)),
                    targets: vec![(1, BlockId(1))],
                    otherwise: BlockId(2),
                    exhaustive_enum_unreachable: false,
                    span: SourceSpan::default(),
                },
            },
            TrustBlock {
                id: BlockId(1),
                stmts: vec![assign_ptr_metadata(LEN, SLICE), assign_lt(COND, INDEX, LEN)],
                terminator: bounds_assert(COND, true, 2),
            },
            TrustBlock { id: BlockId(2), stmts: vec![], terminator: Terminator::Return },
        ];
        assert_eq!(
            bundled_member_assert_admission(&member),
            BundledMemberAssertAdmission::Refused {
                reason: "member has a guarded or non-entry-prefix Assert",
                class: MemberAssertRefusalClass::GuardedOrNonEntryPrefix,
            }
        );
    }

    /// The charge must stay formal-rooted in the sense the gate checks: every
    /// free variable is either a formal or a formal's `__slice_len`, so the
    /// call-site substitution is TOTAL and no member spelling can survive into
    /// the caller's namespace.
    #[test]
    fn every_free_variable_of_the_charge_is_formal_rooted() {
        let BundledMemberAssertAdmission::Derived { param_names, requires } =
            bundled_member_assert_admission(&exact_bounds_member())
        else {
            panic!("the exact entry-prefix BoundsCheck shape must be admitted");
        };
        for require in &requires {
            for (var, _) in trust_types::collect_free_var_decls(require) {
                let root = var.strip_suffix(DERIVED_SLICE_LEN_SUFFIX).unwrap_or(&var);
                assert!(
                    param_names.iter().any(|formal| formal == root),
                    "derived bounds charge names `{var}`, which is not rooted in \
                     {param_names:?}; the call-site substitution would leave it free"
                );
            }
        }
    }

    /// The slice formal is REWRITTEN in the entry prefix before the
    /// `PtrMetadata`, so `slice__slice_len` — which the call-site producer
    /// substitutes from the ENTRY actual — is not the length the Assert compares.
    /// Measured BEFORE this discipline existed: the member was `Derived` with the
    /// charge `self < slice__slice_len`, i.e. it charged the caller a proposition
    /// about a slice the member had already replaced.
    #[test]
    fn a_slice_formal_rewritten_before_the_metadata_read_refuses() {
        let mut member = exact_bounds_member();
        member.body.locals.push(local(5, slice_ref_i32(), None));
        member.body.blocks[0].stmts.insert(
            0,
            Statement::Assign {
                place: Place::local(SLICE),
                rvalue: Rvalue::Use(Operand::Copy(Place::local(5))),
                span: SourceSpan::default(),
            },
        );
        assert_eq!(
            bundled_member_assert_admission(&member),
            BundledMemberAssertAdmission::Refused {
                reason: "member BoundsCheck bound is not the pointer metadata of a slice formal",
                class: MemberAssertRefusalClass::Other,
            }
        );
    }

    /// The same discipline through the ORTHOGONAL channel an `Assign`-destination
    /// scan cannot see: the formal is not written, a MUTABLE ALIAS of it is handed
    /// out, and a store through that alias names the alias rather than the formal.
    #[test]
    fn a_mutably_aliased_slice_formal_refuses() {
        let mut member = exact_bounds_member();
        member.body.locals.push(local(
            5,
            Ty::Ref { mutable: true, inner: Box::new(slice_ref_i32()) },
            None,
        ));
        member.body.blocks[0].stmts.insert(
            0,
            Statement::Assign {
                place: Place::local(5),
                rvalue: Rvalue::Ref { mutable: true, place: Place::local(SLICE) },
                span: SourceSpan::default(),
            },
        );
        assert_eq!(
            bundled_member_assert_admission(&member),
            BundledMemberAssertAdmission::Refused {
                reason: "member BoundsCheck bound is not the pointer metadata of a slice formal",
                class: MemberAssertRefusalClass::Other,
            }
        );
    }

    /// The INDEX formal is rewritten before the comparison. `resolve` used to
    /// answer a formal's ENTRY name as soon as the local was in parameter range,
    /// so the derived charge constrained the caller's argument rather than the
    /// value the Assert compares. Measured before: `Derived`.
    #[test]
    fn an_index_formal_rewritten_before_the_comparison_refuses() {
        let mut member = exact_bounds_member();
        member.body.locals.push(local(5, Ty::usize(), None));
        member.body.blocks[0].stmts.insert(
            0,
            Statement::Assign {
                place: Place::local(INDEX),
                rvalue: Rvalue::Use(Operand::Copy(Place::local(5))),
                span: SourceSpan::default(),
            },
        );
        assert_eq!(
            bundled_member_assert_admission(&member),
            BundledMemberAssertAdmission::Refused {
                reason: "member BoundsCheck index is not uniquely formal-rooted",
                class: MemberAssertRefusalClass::UnrootedOperand,
            }
        );
    }

    /// The stability question is asked about the READ, not about the prefix as a
    /// whole: a write to an UNRELATED local before the operation changes nothing
    /// the charge names, and the member is still admitted. Without this the
    /// discipline above would be indistinguishable from "refuse any member with a
    /// statement before its check".
    #[test]
    fn an_unrelated_write_before_the_check_still_admits() {
        let mut member = exact_bounds_member();
        member.body.locals.push(local(5, Ty::usize(), None));
        member.body.blocks[0].stmts.insert(
            0,
            Statement::Assign {
                place: Place::local(5),
                rvalue: Rvalue::Use(Operand::Constant(ConstValue::Int(7))),
                span: SourceSpan::default(),
            },
        );
        let BundledMemberAssertAdmission::Derived { requires, .. } =
            bundled_member_assert_admission(&member)
        else {
            panic!("a write to an unrelated local must not refuse the member");
        };
        assert_eq!(requires, [expected_charge()]);
    }

    /// A derived charge names only `<formal>` and `<formal>__slice_len`, so the
    /// survival checker the compiler gate runs over each regenerated caller-side
    /// row finds the member spelling in the UNSUBSTITUTED formula...
    #[test]
    fn the_survival_checker_names_an_unsubstituted_member_length() {
        let BundledMemberAssertAdmission::Derived { param_names, requires } =
            bundled_member_assert_admission(&exact_bounds_member())
        else {
            panic!("the exact shape is admitted");
        };
        assert_eq!(
            derived_member_length_var_survives(&param_names, &requires[0]),
            Some("slice__slice_len".to_owned())
        );
    }

    /// ...and finds nothing once the length has been rebound to a caller symbol,
    /// which is the only shape the gate admits.
    #[test]
    fn the_survival_checker_passes_a_fully_substituted_row() {
        let param_names = vec!["self".to_owned(), "slice".to_owned()];
        let substituted = Formula::Lt(
            Box::new(Formula::var("i", Sort::Int)),
            Box::new(Formula::var("s__slice_len", Sort::Int)),
        );
        assert_eq!(derived_member_length_var_survives(&param_names, &substituted), None);
    }

    /// A member mixing a Div/Rem charge and a bounds charge accounts for BOTH.
    /// The population check is all-or-nothing, so a lane that silently dropped
    /// one of them would surface here rather than in a false PROVE.
    #[test]
    fn a_member_mixing_div_and_bounds_charges_accounts_for_both() {
        let mut member = exact_bounds_member();
        member.body.locals.push(local(5, Ty::Bool, None));
        member.body.locals.push(local(6, Ty::usize(), None));
        member.body.blocks = vec![
            TrustBlock {
                id: BlockId(0),
                stmts: vec![assign_ptr_metadata(LEN, SLICE), assign_lt(COND, INDEX, LEN)],
                terminator: bounds_assert(COND, true, 1),
            },
            TrustBlock {
                id: BlockId(1),
                stmts: vec![],
                terminator: Terminator::Assert {
                    cond: Operand::Copy(Place::local(5)),
                    expected: false,
                    msg: AssertMessage::DivisionByZero,
                    target: BlockId(2),
                    unwind: UnwindEdge::Continue,
                    span: SourceSpan::default(),
                },
            },
            TrustBlock {
                id: BlockId(2),
                stmts: vec![Statement::Assign {
                    place: Place::local(6),
                    rvalue: Rvalue::BinaryOp(
                        BinOp::Div,
                        Operand::Copy(Place::local(LEN)),
                        Operand::Copy(Place::local(INDEX)),
                    ),
                    span: SourceSpan::default(),
                }],
                terminator: Terminator::Return,
            },
        ];
        let BundledMemberAssertAdmission::Derived { requires, .. } =
            bundled_member_assert_admission(&member)
        else {
            panic!("both asserts are exactly chargeable, so the member must be admitted");
        };
        assert_eq!(
            requires,
            [
                expected_charge(),
                Formula::Not(Box::new(Formula::Eq(
                    Box::new(Formula::var("self", Sort::Int)),
                    Box::new(Formula::Int(0)),
                ))),
            ]
        );
    }

    // ---- Trust (2026-10-01): member-local discharge against a constant length ----
    //
    // `core::num::imp::int_sqrt`'s `first_stage!` reads a 256-entry table at
    // `(n >> (BITS - 8)) as usize`. Under a release-like std this is the first
    // entry-prefix Assert of `u32_stages`/`u64_stages`, and before the discharge it
    // refused the member as class `Other` ("index is not uniquely formal-rooted"),
    // which refused every bundle reaching `isqrt`. The index provably never reaches
    // 256, so the Assert owes no caller anything.

    const N: usize = 1;
    const SHIFTED: usize = 2;
    const IDX: usize = 3;
    const IN_BOUNDS: usize = 4;
    const ALIAS: usize = 5;

    fn assign(dest: usize, rvalue: Rvalue) -> Statement {
        Statement::Assign { place: Place::local(dest), rvalue, span: SourceSpan::default() }
    }

    fn table_member(formal_ty: Ty, stmts: Vec<Statement>) -> VerifiableFunction {
        VerifiableFunction {
            name: "u32_stages".into(),
            def_path: "core::num::imp::int_sqrt::u32_stages".into(),
            span: SourceSpan::default(),
            body: VerifiableBody {
                locals: vec![
                    local(0, Ty::u32(), None),
                    local(N, formal_ty.clone(), Some("n")),
                    local(SHIFTED, formal_ty, None),
                    local(IDX, Ty::usize(), None),
                    local(IN_BOUNDS, Ty::Bool, None),
                    local(ALIAS, Ty::Ref { mutable: true, inner: Box::new(Ty::u32()) }, None),
                ],
                blocks: vec![
                    TrustBlock {
                        id: BlockId(0),
                        stmts,
                        terminator: bounds_assert(IN_BOUNDS, true, 1),
                    },
                    TrustBlock { id: BlockId(1), stmts: vec![], terminator: Terminator::Return },
                ],
                arg_count: 1,
                return_ty: Ty::u32(),
                datatype_defs: Default::default(),
            },
            contracts: vec![],
            preconditions: vec![],
            postconditions: vec![],
            spec: FunctionSpec::default(),
            tuple_layouts: Default::default(),
        }
    }

    /// `_SHIFTED = Shr(copy _N, const shift)`; `_IDX = copy _SHIFTED as usize`;
    /// `_IN_BOUNDS = Lt(copy _IDX, const len)`.
    fn shifted_table_index(shift: u128, len: u128) -> Vec<Statement> {
        vec![
            assign(
                SHIFTED,
                Rvalue::BinaryOp(
                    BinOp::Shr,
                    Operand::Copy(Place::local(N)),
                    Operand::Constant(ConstValue::Int(shift as i128)),
                ),
            ),
            assign(IDX, Rvalue::Cast(Operand::Copy(Place::local(SHIFTED)), Ty::usize())),
            assign(
                IN_BOUNDS,
                Rvalue::BinaryOp(
                    BinOp::Lt,
                    Operand::Copy(Place::local(IDX)),
                    Operand::Constant(ConstValue::Uint(len, 64)),
                ),
            ),
        ]
    }

    fn refused_as_non_formal_index(admission: BundledMemberAssertAdmission) -> bool {
        matches!(
            admission,
            BundledMemberAssertAdmission::Refused {
                reason: "member BoundsCheck index is not uniquely formal-rooted",
                class: MemberAssertRefusalClass::UnrootedOperand,
            }
        )
    }

    #[test]
    fn a_top_byte_index_into_a_256_entry_table_discharges() {
        let member = table_member(Ty::u32(), shifted_table_index(24, 256));
        assert_eq!(
            bundled_member_assert_admission(&member),
            BundledMemberAssertAdmission::Derived {
                param_names: vec!["n".into()],
                requires: vec![]
            }
        );
        // It owes its callers nothing, exactly as a nonzero constant divisor.
        assert_eq!(member_entry_prefix_assert_requires(&member), None);
        // The `u64_stages` spelling: `n >> 56` of a `u64`.
        let member = table_member(Ty::u64(), shifted_table_index(56, 256));
        assert!(matches!(
            bundled_member_assert_admission(&member),
            BundledMemberAssertAdmission::Derived { ref requires, .. } if requires.is_empty()
        ));
    }

    /// One bit short of the table: `n >> 23` reaches 511, which a 256-entry table
    /// does not hold. Not discharged, and refused exactly as before.
    #[test]
    fn a_shift_one_short_of_the_table_still_refuses() {
        let member = table_member(Ty::u32(), shifted_table_index(23, 256));
        assert!(refused_as_non_formal_index(bundled_member_assert_admission(&member)));
        // The exact edge: `n >> 24` is at most 255, so a 255-entry table is too short.
        let member = table_member(Ty::u32(), shifted_table_index(24, 255));
        assert!(refused_as_non_formal_index(bundled_member_assert_admission(&member)));
    }

    /// A SIGNED operand shifts arithmetically, and a negative value cast to
    /// `usize` is huge: no bound, so no discharge.
    #[test]
    fn a_signed_shifted_index_refuses() {
        let member = table_member(Ty::i32(), shifted_table_index(24, 256));
        assert!(refused_as_non_formal_index(bundled_member_assert_admission(&member)));
    }

    /// A shift amount at or past the width is MASKED by MIR's plain `Shr`, so it
    /// shifts by far less than it says; the bound declines it.
    #[test]
    fn a_shift_amount_at_the_width_refuses() {
        let member = table_member(Ty::u32(), shifted_table_index(32, 256));
        assert!(refused_as_non_formal_index(bundled_member_assert_admission(&member)));
    }

    /// The bound is a property of the ONE definition that reaches the read. A
    /// second whole write of the shifted temp (here, the unshifted formal) before
    /// the cast falls back to the type bound of `u32`, which is not below 256.
    #[test]
    fn a_redefined_index_temp_refuses() {
        let mut stmts = shifted_table_index(24, 256);
        stmts.insert(1, assign(SHIFTED, Rvalue::Use(Operand::Copy(Place::local(N)))));
        let member = table_member(Ty::u32(), stmts);
        assert!(refused_as_non_formal_index(bundled_member_assert_admission(&member)));
    }

    /// A `&mut` alias of the shifted temp handed out before the read can rewrite
    /// it through a place no local-keyed scan sees; the bound declines it.
    #[test]
    fn a_mutably_aliased_index_temp_refuses() {
        let mut stmts = shifted_table_index(24, 256);
        stmts.insert(1, assign(ALIAS, Rvalue::Ref { mutable: true, place: Place::local(SHIFTED) }));
        let member = table_member(Ty::u32(), stmts);
        assert!(refused_as_non_formal_index(bundled_member_assert_admission(&member)));
    }

    /// An index whose TYPE alone bounds it below the length — a `u8` formal cast
    /// to `usize` into a 256-entry table — discharges too.
    #[test]
    fn a_byte_typed_index_into_a_256_entry_table_discharges() {
        let member = table_member(
            Ty::u8(),
            vec![
                assign(IDX, Rvalue::Cast(Operand::Copy(Place::local(N)), Ty::usize())),
                assign(
                    IN_BOUNDS,
                    Rvalue::BinaryOp(
                        BinOp::Lt,
                        Operand::Copy(Place::local(IDX)),
                        Operand::Constant(ConstValue::Uint(256, 64)),
                    ),
                ),
            ],
        );
        assert!(matches!(
            bundled_member_assert_admission(&member),
            BundledMemberAssertAdmission::Derived { ref requires, .. } if requires.is_empty()
        ));
    }

    // ---- Trust (2026-10-01): the entry prefix is SINGLE-ENTRY ----
    //
    // A loop that leaves the prefix through a `SwitchInt` and jumps back into it
    // re-runs a prefix block with values the prefix never wrote. Both the
    // constant-length discharge (its bound comes from the one prefix definition)
    // and the formal charge (it names the formal's ENTRY value) read the prefix
    // as code that runs once from the entry, so a re-entered block and all after
    // it are cut, and an Assert there refuses as the guarded/non-entry gap.

    /// `SwitchInt(copy _local) [0 -> zero], otherwise -> otherwise`.
    fn switch_on(local: usize, zero: usize, otherwise: usize) -> Terminator {
        Terminator::SwitchInt {
            discr: Operand::Copy(Place::local(local)),
            targets: vec![(0, BlockId(zero))],
            otherwise: BlockId(otherwise),
            exhaustive_enum_unreachable: false,
            span: SourceSpan::default(),
        }
    }

    fn refused_off_the_single_entry_prefix(admission: &BundledMemberAssertAdmission) -> bool {
        matches!(
            admission,
            BundledMemberAssertAdmission::Refused {
                class: MemberAssertRefusalClass::GuardedOrNonEntryPrefix,
                ..
            }
        )
    }

    /// The bound `n >> 24 <= 255` comes from the ONE prefix definition of the
    /// shifted temp. A loop body that resets it to the unshifted formal and jumps
    /// back to the index block makes the second read reach `u32::MAX`, which the
    /// 256-entry table does not hold: no discharge, and no charge either.
    #[test]
    fn a_loop_back_into_the_table_index_block_refuses_the_discharge() {
        let looped = |back_edge: bool| {
            let index = shifted_table_index(24, 256);
            let mut member = table_member(Ty::u32(), vec![]);
            member.body.blocks = vec![
                TrustBlock {
                    id: BlockId(0),
                    stmts: vec![index[0].clone()],
                    terminator: Terminator::Goto(BlockId(1)),
                },
                TrustBlock {
                    id: BlockId(1),
                    stmts: index[1..].to_vec(),
                    terminator: bounds_assert(IN_BOUNDS, true, 2),
                },
                TrustBlock { id: BlockId(2), stmts: vec![], terminator: switch_on(N, 4, 3) },
                TrustBlock {
                    id: BlockId(3),
                    stmts: vec![assign(SHIFTED, Rvalue::Use(Operand::Copy(Place::local(N))))],
                    terminator: Terminator::Goto(BlockId(if back_edge { 1 } else { 4 })),
                },
                TrustBlock { id: BlockId(4), stmts: vec![], terminator: Terminator::Return },
            ];
            member
        };
        // Control: the same body leaving instead of looping still discharges, so
        // the refusal below is the back edge's and nothing else's.
        assert!(matches!(
            bundled_member_assert_admission(&looped(false)),
            BundledMemberAssertAdmission::Derived { ref requires, .. } if requires.is_empty()
        ));
        assert!(refused_off_the_single_entry_prefix(&bundled_member_assert_admission(&looped(
            true
        ))));
    }

    /// The formal charge `self < slice__slice_len` names the index's ENTRY value.
    /// A loop body that sets the index to the length and jumps back re-runs the
    /// check on a value the caller never passed and the charge never constrained.
    #[test]
    fn a_loop_back_into_the_formal_index_block_refuses_the_charge() {
        let looped = |back_edge: bool| {
            member(
                slice_ref_i32(),
                vec![
                    TrustBlock {
                        id: BlockId(0),
                        stmts: vec![],
                        terminator: Terminator::Goto(BlockId(1)),
                    },
                    TrustBlock {
                        id: BlockId(1),
                        stmts: vec![assign_ptr_metadata(LEN, SLICE), assign_lt(COND, INDEX, LEN)],
                        terminator: bounds_assert(COND, true, 2),
                    },
                    TrustBlock {
                        id: BlockId(2),
                        stmts: vec![],
                        terminator: switch_on(INDEX, 4, 3),
                    },
                    TrustBlock {
                        id: BlockId(3),
                        stmts: vec![Statement::Assign {
                            place: Place::local(INDEX),
                            rvalue: Rvalue::Use(Operand::Copy(Place::local(LEN))),
                            span: SourceSpan::default(),
                        }],
                        terminator: Terminator::Goto(BlockId(if back_edge { 1 } else { 4 })),
                    },
                    TrustBlock { id: BlockId(4), stmts: vec![], terminator: Terminator::Return },
                ],
            )
        };
        let BundledMemberAssertAdmission::Derived { requires, .. } =
            bundled_member_assert_admission(&looped(false))
        else {
            panic!("the loop-free control must be admitted");
        };
        assert_eq!(requires, [expected_charge()]);
        assert!(refused_off_the_single_entry_prefix(&bundled_member_assert_admission(&looped(
            true
        ))));
    }
}

#[cfg(test)]
mod member_precondition_type_range_tests {
    //! The exact boundary between the extractor's always-true integer
    //! type-range invariant and a DECLARED member contract.
    //!
    //! The bundled-member Assert authority gate admits the derived-requires lane
    //! only for a contract-less member, because that summary REPLACES the
    //! callee's contract at the call site. A type tautology is not such a
    //! contract — it holds for every well-typed actual, so dropping it changes
    //! no proof obligation — but it is attached to EVERY named integer formal,
    //! so failing to tell the two apart refuses every `usize`-indexed member.
    //! Every mutant below must read as a CONTRACT (false), because the cost of
    //! that answer is a refusal and the cost of the other is charging a caller
    //! nothing where a real obligation stood.

    use trust_types::{FunctionSpec, SourceSpan, VerifiableBody, VerifiableFunction};

    use super::*;

    const U64_MAX: i128 = 18_446_744_073_709_551_615;

    fn local(index: usize, ty: Ty, name: Option<&str>) -> LocalDecl {
        LocalDecl { index, ty, name: name.map(str::to_string) }
    }

    fn func(locals: Vec<LocalDecl>, arg_count: usize) -> VerifiableFunction {
        VerifiableFunction {
            name: "member".into(),
            def_path: "test::member".into(),
            span: SourceSpan::default(),
            body: VerifiableBody {
                locals,
                blocks: vec![TrustBlock {
                    id: BlockId(0),
                    stmts: vec![],
                    terminator: Terminator::Return,
                }],
                arg_count,
                return_ty: Ty::Unit,
                datatype_defs: Default::default(),
            },
            contracts: vec![],
            preconditions: vec![],
            postconditions: vec![],
            spec: FunctionSpec::default(),
            tuple_layouts: Default::default(),
        }
    }

    fn range(name: &str, min: i128, max: i128) -> Formula {
        Formula::And(vec![
            Formula::Ge(Box::new(Formula::var(name, Sort::Int)), Box::new(Formula::Int(min))),
            Formula::Le(Box::new(Formula::var(name, Sort::Int)), Box::new(Formula::Int(max))),
        ])
    }

    fn usize_param() -> VerifiableFunction {
        func(vec![local(0, Ty::Unit, None), local(1, Ty::usize(), Some("self"))], 1)
    }

    #[test]
    fn the_exact_unsigned_type_range_is_a_tautology() {
        assert!(member_precondition_is_integer_param_type_range(
            &usize_param(),
            &range("self", 0, U64_MAX)
        ));
    }

    #[test]
    fn the_exact_signed_type_range_is_a_tautology() {
        let signed = func(vec![local(0, Ty::Unit, None), local(1, Ty::i32(), Some("k"))], 1);
        assert!(member_precondition_is_integer_param_type_range(
            &signed,
            &range("k", -2_147_483_648, 2_147_483_647)
        ));
    }

    /// A SHADOWED parameter name renders as the collision-safe `_<index>` in the
    /// extractor's fact. Recognizing the bare name there would bind the
    /// tautology to the wrong local.
    #[test]
    fn a_shadowed_parameter_is_named_by_index_not_by_source_name() {
        let shadowed = func(
            vec![
                local(0, Ty::Unit, None),
                local(1, Ty::usize(), Some("n")),
                local(2, Ty::usize(), Some("n")),
            ],
            1,
        );
        assert!(member_precondition_is_integer_param_type_range(
            &shadowed,
            &range("_1", 0, U64_MAX)
        ));
        assert!(!member_precondition_is_integer_param_type_range(
            &shadowed,
            &range("n", 0, U64_MAX)
        ));
    }

    #[test]
    fn a_tighter_or_wider_bound_is_a_declared_contract() {
        for (min, max) in [(0, 1024), (1, U64_MAX), (0, U64_MAX + 1)] {
            assert!(
                !member_precondition_is_integer_param_type_range(
                    &usize_param(),
                    &range("self", min, max)
                ),
                "bound {min}..={max} is not usize's type range"
            );
        }
    }

    #[test]
    fn a_range_over_a_non_parameter_local_is_not_this_facts_subject() {
        let with_body_local =
            func(vec![local(0, Ty::Unit, None), local(1, Ty::usize(), Some("t"))], 0);
        assert!(!member_precondition_is_integer_param_type_range(
            &with_body_local,
            &range("t", 0, U64_MAX)
        ));
    }

    /// Beyond width 64 the extractor attaches NO fact, so a formula claiming one
    /// did not come from it and is a declared contract.
    #[test]
    fn a_width_outside_the_extractors_envelope_is_not_a_tautology() {
        let wide = func(
            vec![
                local(0, Ty::Unit, None),
                local(1, Ty::Int { width: 128, signed: false }, Some("w")),
            ],
            1,
        );
        assert!(!member_precondition_is_integer_param_type_range(&wide, &range("w", 0, i128::MAX)));
    }

    #[test]
    fn an_extra_conjunct_or_a_mismatched_subject_is_a_declared_contract() {
        let extra = Formula::And(vec![
            Formula::Ge(Box::new(Formula::var("self", Sort::Int)), Box::new(Formula::Int(0))),
            Formula::Le(Box::new(Formula::var("self", Sort::Int)), Box::new(Formula::Int(U64_MAX))),
            Formula::Not(Box::new(Formula::Eq(
                Box::new(Formula::var("self", Sort::Int)),
                Box::new(Formula::Int(7)),
            ))),
        ]);
        assert!(!member_precondition_is_integer_param_type_range(&usize_param(), &extra));

        let mismatched = Formula::And(vec![
            Formula::Ge(Box::new(Formula::var("self", Sort::Int)), Box::new(Formula::Int(0))),
            Formula::Le(
                Box::new(Formula::var("other", Sort::Int)),
                Box::new(Formula::Int(U64_MAX)),
            ),
        ]);
        assert!(!member_precondition_is_integer_param_type_range(&usize_param(), &mismatched));
    }

    #[test]
    fn a_bare_comparison_that_is_not_the_two_conjunct_shape_is_a_declared_contract() {
        let bare =
            Formula::Ge(Box::new(Formula::var("self", Sort::Int)), Box::new(Formula::Int(0)));
        assert!(!member_precondition_is_integer_param_type_range(&usize_param(), &bare));
    }
}

#[cfg(test)]
mod fn_ptr_func_ty_id_scope_tests {
    //! A `Ty::Func(FuncTyId)` minted for a `Ty::FnPtr` must have ONE spelling per
    //! bundle, because the aggregate definitions that EMBED it (`StructDef.fields`)
    //! live in the bundle-wide `type_cache` while the id itself used to be minted
    //! per-FUNCTION (`func_ty_base`). The two scopes disagreeing is what produced
    //!
    //!   bb0: extract_field field type mismatch: expected functy.N, got functy.M
    //!
    //! on every ny-cert body that reads a fn-pointer field out of a cached
    //! aggregate (`std::thread::LocalKey<T> { inner: fn(..) -> *const T }` — the
    //! `try_with` receiver behind `budget::expired`, `rational::ARENA`, ...).

    use trust_types::VerifiableBody;

    use super::*;

    fn fn_i32_to_i32() -> Ty {
        Ty::FnPtr { sig: Box::new(FnSig { params: vec![Ty::i32()], ret: Box::new(Ty::i32()) }) }
    }

    /// `struct Holder { f: fn(i32) -> i32, n: i32 }` — the LocalKey shape: an
    /// aggregate carrying a fn-pointer field.
    fn holder_ty() -> Ty {
        Ty::adt(
            "test::Holder",
            vec![("f".to_string(), fn_i32_to_i32()), ("n".to_string(), Ty::i32())],
        )
    }

    /// `fn first(h: Holder) -> i32 { 7 }`. Its ONLY job is to be lowered FIRST,
    /// so the `Holder` struct (and the `functy` id of its field) is registered
    /// and cached under THIS function's scope.
    fn first_fn() -> VerifiableFunction {
        VerifiableFunction {
            name: "first".to_string(),
            def_path: "test::first".to_string(),
            span: TrustSourceSpan::default(),
            body: VerifiableBody {
                locals: vec![
                    LocalDecl { index: 0, ty: Ty::i32(), name: None },
                    LocalDecl { index: 1, ty: holder_ty(), name: Some("h".into()) },
                ],
                blocks: vec![TrustBlock {
                    id: BlockId(0),
                    stmts: vec![Statement::Assign {
                        place: Place::local(0),
                        rvalue: Rvalue::Use(Operand::Constant(ConstValue::Int(7))),
                        span: TrustSourceSpan::default(),
                    }],
                    terminator: Terminator::Return,
                }],
                arg_count: 1,
                return_ty: Ty::i32(),
                datatype_defs: Default::default(),
            },
            contracts: vec![],
            preconditions: vec![],
            postconditions: vec![],
            spec: Default::default(),
            tuple_layouts: Default::default(),
        }
    }

    /// `fn second(h: Holder) -> fn(i32) -> i32 { h.f }`. Lowered SECOND: it gets
    /// `Holder` from the shared `type_cache` (so the struct's field type is the
    /// FIRST function's `functy` id) and then re-maps `Ty::FnPtr` for the
    /// `extract_field` result type.
    fn second_fn() -> VerifiableFunction {
        VerifiableFunction {
            name: "second".to_string(),
            def_path: "test::second".to_string(),
            span: TrustSourceSpan::default(),
            body: VerifiableBody {
                locals: vec![
                    LocalDecl { index: 0, ty: fn_i32_to_i32(), name: None },
                    LocalDecl { index: 1, ty: holder_ty(), name: Some("h".into()) },
                ],
                blocks: vec![TrustBlock {
                    id: BlockId(0),
                    stmts: vec![Statement::Assign {
                        place: Place::local(0),
                        rvalue: Rvalue::Use(Operand::Copy(Place {
                            local: 1,
                            projections: vec![Projection::Field(0)],
                        })),
                        span: TrustSourceSpan::default(),
                    }],
                    terminator: Terminator::Return,
                }],
                arg_count: 1,
                return_ty: fn_i32_to_i32(),
                datatype_defs: Default::default(),
            },
            contracts: vec![],
            preconditions: vec![],
            postconditions: vec![],
            spec: Default::default(),
            tuple_layouts: Default::default(),
        }
    }

    #[test]
    fn a_fn_pointer_field_read_out_of_a_cached_aggregate_is_well_typed() {
        let funcs = vec![first_fn(), second_fn()];
        let module =
            lower_to_trust_ir_functions("fnptr_scope", &funcs).expect("the bundle must lower");

        // The struct is registered ONCE (bundle-wide `type_cache` hit).
        let holder = module
            .structs
            .iter()
            .find(|s| s.name == "test::Holder")
            .expect("the Holder struct must be registered");
        let field_ty = holder.fields[0].ty.clone();
        assert!(
            matches!(field_ty, TrustIrTy::Func(_)),
            "the fn-pointer field must map to Ty::Func, got {field_ty}"
        );

        // Every `extract_field` of that field must DECLARE the same `functy` id
        // the struct definition records.
        let mut seen = 0usize;
        for func in &module.functions {
            for block in &func.blocks {
                for node in &block.body {
                    if let Inst::ExtractField { ty, field: 0, .. } = &node.inst
                        && matches!(ty, TrustIrTy::Func(_))
                    {
                        seen += 1;
                        assert_eq!(
                            *ty, field_ty,
                            "function '{}' extract_field declares {ty} but \
                             '{}' field 0 is {field_ty}",
                            func.name, holder.name
                        );
                    }
                }
            }
        }
        assert_eq!(seen, 1, "the fn-pointer field read must be lowered exactly once");

        let errors = trust_ir_build::validate_module(&module);
        assert!(errors.is_empty(), "module must validate: {errors:?}");
    }
}

#[cfg(test)]
mod opaque_const_call_arg_conformance_tests {
    //! A `ConstValue::OpaqueConst` (an aggregate/reference constant whose contents
    //! the extractor does not model — `ny_cert::rational::Rat::ZERO`, a `&[&str]`
    //! table, a promoted ref) has NO intrinsic type. The contextless `emit_const`
    //! hardcodes the byte-slice fat spelling `FatPtr(Slice(u8))`, which is ill-typed
    //! the moment the CONSUMER declares anything else. At a LINKED call the consumer
    //! IS known — the callee's declared param type — and the mismatch was fatal:
    //!
    //!   bb2: call to core::option::Option::<ny_cert::rational::Rat>::unwrap_or
    //!        arg 1 type mismatch: expected struct.1, got fatptr<slice ty.0>
    //!
    //! `resolve_operand_as_trust_type` already carries the conforming arm; the call
    //! seam simply never routed a non-integer constant to it.

    use trust_types::{UnwindEdge, VerifiableBody};

    use super::*;

    /// `struct Rat { id: u32 }` — an aggregate whose associated consts the
    /// extractor cannot evaluate (`ConstValue::OpaqueConst`).
    fn rat_ty() -> Ty {
        Ty::adt("test::Rat", vec![("id".to_string(), Ty::Int { width: 32, signed: false })])
    }

    /// `fn unwrap_or_like(d: Rat) -> u32 { 0 }` — the in-bundle callee whose
    /// DECLARED param type the call argument must conform to.
    fn callee() -> VerifiableFunction {
        VerifiableFunction {
            name: "unwrap_or_like".to_string(),
            def_path: "test::unwrap_or_like".to_string(),
            span: TrustSourceSpan::default(),
            body: VerifiableBody {
                locals: vec![
                    LocalDecl { index: 0, ty: Ty::Int { width: 32, signed: false }, name: None },
                    LocalDecl { index: 1, ty: rat_ty(), name: Some("d".into()) },
                ],
                blocks: vec![TrustBlock {
                    id: BlockId(0),
                    stmts: vec![Statement::Assign {
                        place: Place::local(0),
                        rvalue: Rvalue::Use(Operand::Constant(ConstValue::Uint(0, 32))),
                        span: TrustSourceSpan::default(),
                    }],
                    terminator: Terminator::Return,
                }],
                arg_count: 1,
                return_ty: Ty::Int { width: 32, signed: false },
                datatype_defs: Default::default(),
            },
            contracts: vec![],
            preconditions: vec![],
            postconditions: vec![],
            spec: Default::default(),
            tuple_layouts: Default::default(),
        }
    }

    /// `fn caller() -> u32 { unwrap_or_like(const Rat::ZERO) }` — the constant is
    /// passed DIRECTLY as the call operand, exactly as rustc MIR spells it.
    fn caller() -> VerifiableFunction {
        VerifiableFunction {
            name: "caller".to_string(),
            def_path: "test::caller".to_string(),
            span: TrustSourceSpan::default(),
            body: VerifiableBody {
                locals: vec![
                    LocalDecl { index: 0, ty: Ty::Int { width: 32, signed: false }, name: None },
                    LocalDecl { index: 1, ty: Ty::Int { width: 32, signed: false }, name: None },
                ],
                blocks: vec![
                    TrustBlock {
                        id: BlockId(0),
                        stmts: vec![],
                        terminator: Terminator::Call {
                            unwind: UnwindEdge::Unreachable,
                            is_unsafe_sig: false,
                            callee_identity: None,
                            callee_key: None,
                            is_foreign: false,
                            func: "test::unwrap_or_like".to_string(),
                            args: vec![Operand::Constant(ConstValue::opaque_const())],
                            dest: Place::local(1),
                            target: Some(BlockId(1)),
                            span: TrustSourceSpan::default(),
                            atomic: None,
                        },
                    },
                    TrustBlock {
                        id: BlockId(1),
                        stmts: vec![Statement::Assign {
                            place: Place::local(0),
                            rvalue: Rvalue::Use(Operand::Copy(Place::local(1))),
                            span: TrustSourceSpan::default(),
                        }],
                        terminator: Terminator::Return,
                    },
                ],
                arg_count: 0,
                return_ty: Ty::Int { width: 32, signed: false },
                datatype_defs: Default::default(),
            },
            contracts: vec![],
            preconditions: vec![],
            postconditions: vec![],
            spec: Default::default(),
            tuple_layouts: Default::default(),
        }
    }

    #[test]
    fn an_opaque_constant_argument_conforms_to_the_declared_param_type() {
        let funcs = vec![caller(), callee()];
        let module =
            lower_to_trust_ir_functions("opaque_arg", &funcs).expect("the bundle must lower");

        let rat = module
            .structs
            .iter()
            .find(|s| s.name == "test::Rat")
            .expect("the Rat struct must be registered");
        let rat_ir = TrustIrTy::Struct(rat.id);

        // The havoc standing in for the unevaluable constant must carry the
        // CALLEE's declared param sort, not the contextless byte-slice fat
        // spelling — and must be stamped, or the native input gate fail-closes
        // the bundle on `executes Undef` instead (a message swap, not a fix).
        let caller_fn = module
            .functions
            .iter()
            .find(|f| f.name == "caller")
            .expect("the caller must be lowered");
        let mut havocs = 0usize;
        for block in &caller_fn.blocks {
            for node in &block.body {
                if let Inst::Undef { ty } = &node.inst {
                    havocs += 1;
                    assert_eq!(
                        *ty, rat_ir,
                        "the opaque constant argument must be havoc'd at the declared \
                         param type, got {ty}"
                    );
                    assert!(
                        node.proofs
                            .iter()
                            .any(|p| matches!(p, ProofAnnotation::FreshSymbolicHavoc)),
                        "a bridge-emitted Undef must carry FreshSymbolicHavoc or the \
                         native input gate rejects the whole bundle"
                    );
                }
            }
        }
        assert_eq!(havocs, 1, "exactly one opaque-constant havoc is expected");

        let errors = trust_ir_build::validate_module(&module);
        assert!(errors.is_empty(), "module must validate: {errors:?}");
    }
}

#[cfg(test)]
mod layout_sensitive_cast_fallback_tests {
    //! Every bridge-registered struct carries `size: None` on the verifier lanes,
    //! so the `Rvalue::Cast` fall-through's width-less `Bitcast` default emitted
    //! casts the module validator then rejected wholesale:
    //!
    //!   bb2: cast bitcast from struct.65 to struct.65 lacks valid layout evidence
    //!   bb0: cast bitcast from struct.4 to fatptr<dyn.N> lacks valid layout evidence
    //!
    //! The producer must ask the SAME question the validator asks
    //! (`Module::layout_sensitive_cast_evidence`) and never emit an instruction that
    //! cannot answer it.

    use trust_types::VerifiableBody;

    use super::*;

    fn rat_ty() -> Ty {
        Ty::adt("test::Rat", vec![("id".to_string(), Ty::Int { width: 32, signed: false })])
    }

    fn other_ty() -> Ty {
        Ty::adt("test::Other", vec![("a".to_string(), Ty::i64()), ("b".to_string(), Ty::i64())])
    }

    /// `fn cast_fn(a: In) -> Out { transmute(a) }`, spelled as the extractor's
    /// `Rvalue::Cast(Copy(_1), Out)`.
    fn cast_fn(from: Ty, to: Ty) -> VerifiableFunction {
        VerifiableFunction {
            name: "cast_fn".to_string(),
            def_path: "test::cast_fn".to_string(),
            span: TrustSourceSpan::default(),
            body: VerifiableBody {
                locals: vec![
                    LocalDecl { index: 0, ty: to.clone(), name: None },
                    LocalDecl { index: 1, ty: from, name: Some("a".into()) },
                ],
                blocks: vec![TrustBlock {
                    id: BlockId(0),
                    stmts: vec![Statement::Assign {
                        place: Place::local(0),
                        rvalue: Rvalue::Cast(Operand::Copy(Place::local(1)), to.clone()),
                        span: TrustSourceSpan::default(),
                    }],
                    terminator: Terminator::Return,
                }],
                arg_count: 1,
                return_ty: to,
                datatype_defs: Default::default(),
            },
            contracts: vec![],
            preconditions: vec![],
            postconditions: vec![],
            spec: Default::default(),
            tuple_layouts: Default::default(),
        }
    }

    #[test]
    fn an_identity_reinterpret_forwards_the_operand_instead_of_a_bitcast() {
        let module =
            lower_to_trust_ir(&cast_fn(rat_ty(), rat_ty())).expect("the function must lower");

        for block in &module.functions[0].blocks {
            for node in &block.body {
                assert!(
                    !matches!(&node.inst, Inst::Cast { .. }),
                    "a src == dst reinterpret is the identity and must emit NO cast, got {:?}",
                    node.inst
                );
                assert!(
                    !matches!(&node.inst, Inst::Undef { .. }),
                    "an identity reinterpret must FORWARD the value exactly, never havoc it"
                );
            }
        }

        let errors = trust_ir_build::validate_module(&module);
        assert!(errors.is_empty(), "module must validate: {errors:?}");
    }

    /// NEGATIVE CONTROL — the scope line. A reinterpret between DIFFERENT TrustIr
    /// types is NOT an identity, so it keeps emitting the layout-sensitive
    /// `Bitcast` and stays a VISIBLE
    /// `layout_evidence::collect_layout_sensitive_cast_blockers` blocker. The
    /// decompilation / binary-provenance lane refuses a lifted module on exactly
    /// that signal; silencing it with a havoc would be a weakening, not a fix.
    #[test]
    fn a_non_identity_unevidenceable_reinterpret_stays_a_visible_blocker() {
        let module =
            lower_to_trust_ir(&cast_fn(rat_ty(), other_ty())).expect("the function must lower");

        let casts = module.functions[0]
            .blocks
            .iter()
            .flat_map(|b| b.body.iter())
            .filter(|n| matches!(&n.inst, Inst::Cast { .. }))
            .count();
        assert_eq!(casts, 1, "a non-identity reinterpret must still be emitted as a cast");

        assert!(
            !crate::layout_evidence::collect_layout_sensitive_cast_blockers(&module).is_empty(),
            "the unevidenceable cast must remain reportable to the decompilation lane"
        );
    }
}

#[cfg(test)]
mod generic_relink_signature_conformance_tests {
    //! A bundled GENERIC local body is lowered ONCE, pre-monomorphization, with its
    //! type parameters erased (`Ty::Unsupported{kind:"TyKind::Param"} -> Unit`). A
    //! MONOMORPHIZED call re-linked to that body therefore passes a concrete value
    //! into a `Unit`-declared parameter and reads a concrete value out of a
    //! `()`-returning signature:
    //!
    //!   bb2: call to err_barrier arg 0 type mismatch: expected (), got struct.26
    //!   bb0: call declares 1 SSA results, expected 0
    //!
    //! Both diagnostics are ONE defect and they fail full module validation.

    use trust_types::{UnwindEdge, VerifiableBody};

    use super::*;

    fn param_ty() -> Ty {
        Ty::Unsupported { kind: "TyKind::Param".to_string(), detail: "E".to_string() }
    }

    fn err_ty() -> Ty {
        Ty::adt("test::MyErr", vec![("code".to_string(), Ty::Int { width: 32, signed: false })])
    }

    /// `fn err_barrier<E>(e: E) -> E { e }` — the ny-cert identity barrier, lowered
    /// generically (`E` erased to `Unit`).
    fn err_barrier() -> VerifiableFunction {
        VerifiableFunction {
            name: "err_barrier".to_string(),
            def_path: "test::err_barrier".to_string(),
            span: TrustSourceSpan::default(),
            body: VerifiableBody {
                locals: vec![
                    LocalDecl { index: 0, ty: param_ty(), name: None },
                    LocalDecl { index: 1, ty: param_ty(), name: Some("e".into()) },
                ],
                blocks: vec![TrustBlock {
                    id: BlockId(0),
                    stmts: vec![Statement::Assign {
                        place: Place::local(0),
                        rvalue: Rvalue::Use(Operand::Copy(Place::local(1))),
                        span: TrustSourceSpan::default(),
                    }],
                    terminator: Terminator::Return,
                }],
                arg_count: 1,
                return_ty: param_ty(),
                datatype_defs: Default::default(),
            },
            contracts: vec![],
            preconditions: vec![],
            postconditions: vec![],
            spec: Default::default(),
            tuple_layouts: Default::default(),
        }
    }

    /// `fn caller(e: MyErr) -> MyErr { err_barrier::<MyErr>(e) }`.
    fn caller() -> VerifiableFunction {
        VerifiableFunction {
            name: "caller".to_string(),
            def_path: "test::caller".to_string(),
            span: TrustSourceSpan::default(),
            body: VerifiableBody {
                locals: vec![
                    LocalDecl { index: 0, ty: err_ty(), name: None },
                    LocalDecl { index: 1, ty: err_ty(), name: Some("e".into()) },
                    LocalDecl { index: 2, ty: err_ty(), name: None },
                ],
                blocks: vec![
                    TrustBlock {
                        id: BlockId(0),
                        stmts: vec![],
                        terminator: Terminator::Call {
                            unwind: UnwindEdge::Unreachable,
                            is_unsafe_sig: false,
                            callee_identity: None,
                            callee_key: None,
                            is_foreign: false,
                            func: "test::err_barrier::<test::MyErr>".to_string(),
                            args: vec![Operand::Copy(Place::local(1))],
                            dest: Place::local(2),
                            target: Some(BlockId(1)),
                            span: TrustSourceSpan::default(),
                            atomic: None,
                        },
                    },
                    TrustBlock {
                        id: BlockId(1),
                        stmts: vec![Statement::Assign {
                            place: Place::local(0),
                            rvalue: Rvalue::Use(Operand::Copy(Place::local(2))),
                            span: TrustSourceSpan::default(),
                        }],
                        terminator: Terminator::Return,
                    },
                ],
                arg_count: 1,
                return_ty: err_ty(),
                datatype_defs: Default::default(),
            },
            contracts: vec![],
            preconditions: vec![],
            postconditions: vec![],
            spec: Default::default(),
            tuple_layouts: Default::default(),
        }
    }

    #[test]
    fn a_monomorphized_call_to_a_generic_bundled_body_stays_well_typed() {
        let funcs = vec![caller(), err_barrier()];
        let module = lower_to_trust_ir_functions("relink", &funcs).expect("the bundle must lower");

        // The identity body is forwarded, not called: no mistyped `Call` edge and
        // therefore no `call declares 1 SSA results, expected 0` either.
        let caller_fn =
            module.functions.iter().find(|f| f.name == "caller").expect("caller lowers");
        assert!(
            !caller_fn
                .blocks
                .iter()
                .flat_map(|b| b.body.iter())
                .any(|n| matches!(&n.inst, Inst::Call { .. })),
            "the proven identity body must be forwarded, not called with an erased signature"
        );

        let errors = trust_ir_build::validate_module(&module);
        assert!(errors.is_empty(), "module must validate: {errors:?}");
    }

    /// NEGATIVE CONTROL — the fail-closed default. The SAME monomorphized re-link
    /// against a body that is NOT a proven sole-parameter identity keeps the
    /// ordinary `AsWritten` call; nothing is forwarded on a name/shape guess.
    #[test]
    fn a_non_identity_generic_body_is_never_identity_forwarded() {
        let mut not_identity = err_barrier();
        // `fn f<E>(e: E) -> E { <const 0> }` — a constant return, not a projection.
        not_identity.body.blocks[0].stmts[0] = Statement::Assign {
            place: Place::local(0),
            rvalue: Rvalue::Use(Operand::Constant(ConstValue::Unit)),
            span: TrustSourceSpan::default(),
        };
        let funcs = vec![caller(), not_identity];
        let module =
            lower_to_trust_ir_functions("relink_neg", &funcs).expect("the bundle must lower");
        let caller_fn =
            module.functions.iter().find(|f| f.name == "caller").expect("caller lowers");
        assert!(
            caller_fn
                .blocks
                .iter()
                .flat_map(|b| b.body.iter())
                .any(|n| matches!(&n.inst, Inst::Call { .. })),
            "a non-identity body must keep the fail-closed call, never an identity forward"
        );
    }
}

/// True iff `callee`'s leaf segment is `collect`, under ANY path spelling.
///
/// Companion to the qualified-trait-method arm of the B62 closure-inlining narrowing.
/// `qualified_callee_trait_method` begins `callee.strip_prefix('<')?`, so it recognises
/// ONLY the `<Self as Trait>::method` form; an inherent path such as
/// `core::option::Option::<u32>::map::<{closure#0}>` returns `None` there and skipped the
/// narrowing entirely. Keyed on the leaf segment after `strip_generics`, matching the
/// existing inherent-path precedent `callee_is_collection_retain`.
fn callee_leaf_is_collect(callee: &str) -> bool {
    strip_generics(callee).rsplit("::").next() == Some("collect")
}

#[cfg(test)]
mod unconsumed_closure_environment_tests {
    use trust_ir::inst::Inst;
    use trust_ir::node::InstrNode;
    use trust_ir::proof::{
        ObligationKind, ObligationSite, ProofAnnotation, ProofObligation, ProofStatus,
    };
    use trust_ir::value::{BlockId, ClosureTyId, FuncId, FuncTyId, ProofId, ValueId};
    use trust_ir::{Block, Function};

    use super::{TrustIrTy, model_unconsumed_closure_environments, reference_of};

    fn v(id: u32) -> ValueId {
        ValueId::new(id)
    }

    /// The measured a3d shape: `file_len` spilled to a stack cell in the entry
    /// block, read there, then borrowed into a closure environment in a later
    /// block that nothing consumes.
    ///
    /// `capture_root` is what the environment's reference points at — the cell for
    /// the recognized shape, or something else for the negative controls. The
    /// reference is spelled as the bridge spells one: a `Copy` of the address
    /// carrying the borrow claim (trust-ir SPEC "A Rust reference carries no
    /// permission instruction").
    fn function_with_environment(capture_root: ValueId, consume_env: bool) -> Function {
        let mut function =
            Function::new(FuncId::new(0), "caller", FuncTyId::new(0), BlockId::new(0));

        let mut entry = Block::new(BlockId::new(0)).with_param(v(0), TrustIrTy::U64);
        // v(1): the stack cell.
        entry.body.push(
            InstrNode::new(Inst::Alloca { ty: TrustIrTy::U64, count: None, align: None })
                .with_result(v(1)),
        );
        entry.body.push(InstrNode::new(Inst::Store {
            ty: TrustIrTy::U64,
            ptr: v(1),
            value: v(0),
            volatile: false,
            align: None,
        }));
        entry.body.push(
            InstrNode::new(Inst::Load {
                ty: TrustIrTy::U64,
                ptr: v(1),
                volatile: false,
                align: None,
            })
            .with_result(v(2)),
        );
        entry.body.push(InstrNode::new(Inst::Br { target: BlockId::new(1), args: Vec::new() }));

        let mut tail = Block::new(BlockId::new(1));
        tail.body.push(reference(capture_root, v(3)));
        tail.body.push(
            InstrNode::new(Inst::Undef { ty: TrustIrTy::Closure(ClosureTyId::new(0)) })
                .with_result(v(4)),
        );
        tail.body.push(
            InstrNode::new(Inst::InsertField {
                ty: TrustIrTy::Closure(ClosureTyId::new(0)),
                aggregate: v(4),
                field: 0,
                value: v(3),
            })
            .with_result(v(5)),
        );
        if consume_env {
            tail.body.push(
                InstrNode::new(Inst::Call { callee: FuncId::new(1), args: vec![v(5)] })
                    .with_result(v(6)),
            );
        }
        tail.body.push(InstrNode::new(Inst::Return { values: vec![v(2)] }));

        function.blocks.push(entry);
        function.blocks.push(tail);
        function
    }

    /// The bridge's spelling of `&mut *root`, bound to `result`.
    fn reference(root: ValueId, result: ValueId) -> InstrNode {
        InstrNode::new(Inst::Copy { ty: TrustIrTy::Ptr, operand: root })
            .with_result(result)
            .with_proof(ProofAnnotation::UniqueBorrow)
    }

    fn instruction_counts(function: &Function) -> Vec<usize> {
        function.blocks.iter().map(|block| block.body.len()).collect()
    }

    fn tail_insts(function: &Function) -> Vec<&Inst> {
        function.blocks[1].body.iter().map(|node| &node.inst).collect()
    }

    fn havoc_store_through(function: &Function, cell: ValueId) -> bool {
        function.blocks.iter().any(|block| {
            block.body.iter().any(|node| {
                matches!(
                    &node.inst,
                    Inst::Store { ty: TrustIrTy::U64, ptr, value, .. }
                        if *ptr == cell
                            && block.body.iter().any(|def| {
                                def.results.contains(value)
                                    && matches!(def.inst, Inst::Undef { .. })
                            })
                )
            })
        })
    }

    fn borrow_survives(function: &Function) -> bool {
        function
            .blocks
            .iter()
            .any(|block| block.body.iter().any(|node| reference_of(node).is_some()))
    }

    /// ASSERT 1 — the recognized shape is compensated, not merely deleted: the
    /// reference is gone AND a havoc write through the captured cell replaced it.
    /// Killed by the no-op mutant (early `return`).
    #[test]
    fn an_unconsumed_environment_becomes_a_havoc_write_through_its_capture() {
        let mut function = function_with_environment(v(1), false);
        let before = instruction_counts(&function);
        model_unconsumed_closure_environments(&mut function, &[]);
        assert!(
            !borrow_survives(&function),
            "the escaping borrow must be gone: {:?}",
            tail_insts(&function)
        );
        assert!(
            havoc_store_through(&function, v(1)),
            "the captured cell must receive an unconstrained store: {:?}",
            tail_insts(&function)
        );
        // ASSERT 2 — index-preserving, so no `ObligationSite` can drift.
        assert_eq!(before, instruction_counts(&function));
    }

    /// ASSERT 3 — an environment that IS consumed is left exactly as it was; its
    /// captures must stay visibly escaping. Killed by an over-eager mutant that
    /// drops the "terminal result has no reader" test.
    #[test]
    fn a_consumed_environment_is_left_alone() {
        let mut function = function_with_environment(v(1), true);
        let before = function.clone();
        model_unconsumed_closure_environments(&mut function, &[]);
        assert_eq!(before, function);
        assert!(borrow_survives(&function));
    }

    /// ASSERT 4 — a capture whose root is NOT an `Alloca` of this function (here
    /// a block parameter) cannot be compensated, so nothing is rewritten. Killed
    /// by a mutant that accepts any root.
    #[test]
    fn a_capture_not_rooted_at_a_local_cell_is_left_alone() {
        let mut function = function_with_environment(v(0), false);
        let before = function.clone();
        model_unconsumed_closure_environments(&mut function, &[]);
        assert_eq!(before, function);
        assert!(borrow_survives(&function));
    }

    /// ASSERT 5 — a second reader of the environment's captured pointer means the
    /// pointer is observable outside the environment, so the pass declines.
    /// Killed by a mutant that drops the `reader_count == 1` test.
    #[test]
    fn a_capture_with_a_second_reader_is_left_alone() {
        let mut function = function_with_environment(v(1), false);
        let terminator = function.blocks[1].body.pop().expect("terminator");
        function.blocks[1].body.push(
            InstrNode::new(Inst::Load {
                ty: TrustIrTy::U64,
                ptr: v(3),
                volatile: false,
                align: None,
            })
            .with_result(v(7)),
        );
        function.blocks[1].body.push(terminator);
        let before = function.clone();
        model_unconsumed_closure_environments(&mut function, &[]);
        assert_eq!(before, function);
        assert!(borrow_survives(&function));
    }

    /// ASSERT 6a — an instruction that already anchors proof evidence is never
    /// rewritten out from under its `ObligationSite`. This sites the obligation on
    /// the environment's `Borrow` (instruction 0 of the tail block), the LINK-side
    /// guard. Killed by a mutant that drops the link `sited` test.
    #[test]
    fn a_sited_capture_link_is_never_rewritten() {
        let mut function = function_with_environment(v(1), false);
        let sited = vec![obligation_sited_at(1, 0)];
        let before = function.clone();
        model_unconsumed_closure_environments(&mut function, &sited);
        assert_eq!(before, function);
        assert!(borrow_survives(&function));
    }

    /// ASSERT 6b — the SAME guard on the other side: the obligation sits on the
    /// terminal `InsertField` (instruction 2 of the tail block). Two asserts
    /// because the two positions are checked by two different lines, and a mutant
    /// that drops only one of them must still be killed.
    #[test]
    fn a_sited_environment_insert_is_never_rewritten() {
        let mut function = function_with_environment(v(1), false);
        let sited = vec![obligation_sited_at(1, 2)];
        let before = function.clone();
        model_unconsumed_closure_environments(&mut function, &sited);
        assert_eq!(before, function);
        assert!(borrow_survives(&function));
    }

    /// ASSERT 8 — a capture whose root IS an instruction but is NOT a local
    /// `Alloca` (here a pointer LOADED out of memory, whose pointee this function
    /// cannot name, let alone havoc) is left alone. Killed by a mutant that widens
    /// the root grammar past `Alloca`.
    ///
    /// This is the assert the block-parameter control could not make: a block
    /// parameter has no defining instruction at all, so it is refused one step
    /// EARLIER and says nothing about the root test itself.
    #[test]
    fn a_capture_rooted_at_a_loaded_pointer_is_left_alone() {
        let mut function = function_with_environment(v(1), false);
        // Re-point the environment's borrow at a pointer read out of the cell.
        function.blocks[0].body.insert(
            3,
            InstrNode::new(Inst::Load {
                ty: TrustIrTy::Ptr,
                ptr: v(1),
                volatile: false,
                align: None,
            })
            .with_result(v(9)),
        );
        function.blocks[1].body[0] = reference(v(9), v(3));
        let before = function.clone();
        model_unconsumed_closure_environments(&mut function, &before_obligations());
        assert_eq!(before, function);
        assert!(borrow_survives(&function));
    }

    fn before_obligations() -> Vec<ProofObligation> {
        Vec::new()
    }

    /// ASSERT 9 — only a REFERENCE (a `Copy` carrying the `SharedBorrow` /
    /// `UniqueBorrow` claim) is a capture link. A claim-free `Copy` of the cell
    /// (`&raw const`, an operand materialization) is not, so the environment is
    /// left alone. Killed by a mutant whose `reference_of` ignores the claim.
    #[test]
    fn a_claim_free_copy_capture_is_left_alone() {
        let mut function = function_with_environment(v(1), false);
        function.blocks[1].body[0] =
            InstrNode::new(Inst::Copy { ty: TrustIrTy::Ptr, operand: v(1) }).with_result(v(3));
        let before = function.clone();
        model_unconsumed_closure_environments(&mut function, &[]);
        assert_eq!(before, function);
        assert!(!havoc_store_through(&function, v(1)));
    }

    /// The permission instructions are not a capture link either: this bridge
    /// spells no reference as one, so a `Borrow` is an unrecognized shape and the
    /// environment is left alone.
    #[test]
    fn a_permission_instruction_capture_is_left_alone() {
        let mut function = function_with_environment(v(1), false);
        function.blocks[1].body[0] = InstrNode::new(Inst::Borrow { ptr: v(1) }).with_result(v(3));
        let before = function.clone();
        model_unconsumed_closure_environments(&mut function, &[]);
        assert_eq!(before, function);
    }

    fn obligation_sited_at(block: u32, inst_index: u32) -> ProofObligation {
        ProofObligation::new(
            ProofId::new(0),
            ObligationKind::PanicFreedom,
            ProofStatus::Pending,
            "sited on part of the environment construction".to_string(),
        )
        .with_function(FuncId::new(0))
        .with_site(ObligationSite::new(FuncId::new(0), BlockId::new(block), inst_index))
    }

    /// ASSERT 7 — an operand list this crate does not enumerate abandons the WHOLE
    /// pass rather than treating unseen reads as absent. Killed by a mutant that
    /// answers `false` (enumerable) on the fallback arm.
    #[test]
    fn an_unenumerated_instruction_abandons_the_pass() {
        let mut function = function_with_environment(v(1), false);
        let terminator = function.blocks[1].body.pop().expect("terminator");
        // `CloseFrame` READS `v(3)` — the environment's captured pointer — and is
        // outside `enumerated_operand_reads`. Treating it as "no reads" would make
        // the pointer look private to the environment, which is exactly the shape
        // the fail-closed arm exists to refuse.
        function.blocks[1].body.push(InstrNode::new(Inst::CloseFrame { frame: v(3) }));
        function.blocks[1].body.push(terminator);
        let before = function.clone();
        model_unconsumed_closure_environments(&mut function, &[]);
        assert_eq!(before, function);
        assert!(borrow_survives(&function));
    }

    /// The complete constructors (`MakeAggregate { variant: None }`, `ArraySplat`),
    /// which the bridge emits for every checked `+ - *` pack and every complete
    /// struct, tuple or array literal, each reading `probe`: a three-lane
    /// `MakeAggregate` with `probe` at lane 0, 1 and 2 in turn (the other lanes read
    /// `filler`), then an `ArraySplat` of it. Every position is probed so that an
    /// arm reading only some lanes is caught.
    fn complete_constructors_reading(probe: ValueId, filler: ValueId) -> Vec<Inst> {
        let mut constructors: Vec<Inst> = (0..3)
            .map(|position| Inst::MakeAggregate {
                ty: TrustIrTy::Tuple(vec![TrustIrTy::Ptr, TrustIrTy::Ptr, TrustIrTy::Ptr]),
                variant: None,
                fields: (0..3).map(|lane| if lane == position { probe } else { filler }).collect(),
            })
            .collect();
        constructors.push(Inst::ArraySplat {
            ty: TrustIrTy::Array(trust_ir::value::TyId::new(0), 2),
            value: probe,
        });
        constructors
    }

    /// A complete constructor must not stop the closure-environment pass: both arms
    /// of `enumerated_operand_reads` read only their lanes, so an unrelated
    /// constructor in the function is enumerable and the compensation still happens.
    /// Killed by dropping either arm (the pass then abandons the function).
    #[test]
    fn an_unconsumed_environment_is_compensated_beside_a_complete_constructor() {
        for constructor in complete_constructors_reading(v(0), v(2)) {
            let mut function = function_with_environment(v(1), false);
            let terminator = function.blocks[1].body.pop().expect("terminator");
            function.blocks[1].body.push(InstrNode::new(constructor.clone()).with_result(v(7)));
            function.blocks[1].body.push(terminator);
            model_unconsumed_closure_environments(&mut function, &[]);
            assert!(!borrow_survives(&function), "{constructor:?}: {:?}", tail_insts(&function));
            assert!(havoc_store_through(&function, v(1)), "{constructor:?}");
        }
    }

    /// The soundness half: every constructor lane IS a read, so an environment
    /// packed into an aggregate, at any lane, is consumed and left alone. Killed by
    /// an arm that enumerates no lanes or only some of them.
    #[test]
    fn an_environment_packed_into_a_complete_constructor_is_consumed() {
        for constructor in complete_constructors_reading(v(5), v(2)) {
            let mut function = function_with_environment(v(1), false);
            let terminator = function.blocks[1].body.pop().expect("terminator");
            function.blocks[1].body.push(InstrNode::new(constructor.clone()).with_result(v(7)));
            function.blocks[1].body.push(terminator);
            let before = function.clone();
            model_unconsumed_closure_environments(&mut function, &[]);
            assert_eq!(before, function, "{constructor:?} reads the environment");
        }
    }
}

/// The production guard walks ([`reconstruct_sound_dominating_guards_memo`],
/// [`reconstruct_reachability_condition_memo`]) against the reference
/// enumerations they replaced, on every committed fixture and on the shapes
/// that made the reference exponential — for EVERY target, sharing one memo
/// across targets the way `generate_native_safety_vcs_with_module` does.
#[cfg(test)]
mod guard_walk_agreement {
    use trust_types::{SourceSpan, UnwindEdge, VerifiableBody};

    use super::*;

    fn corpus() -> Vec<VerifiableFunction> {
        [
            include_str!("../fixtures/add_ovf.json"),
            include_str!("../fixtures/add1_u32.json"),
            include_str!("../fixtures/both.json"),
            include_str!("../fixtures/clamp_branch.json"),
            include_str!("../fixtures/count.json"),
            include_str!("../fixtures/cst.json"),
            include_str!("../fixtures/dv.json"),
            include_str!("../fixtures/idx.json"),
            include_str!("../fixtures/mul.json"),
            include_str!("../fixtures/mul2_u32.json"),
            include_str!("../fixtures/ng.json"),
            include_str!("../fixtures/pick.json"),
            include_str!("../fixtures/pre.json"),
            include_str!("../fixtures/rem.json"),
            include_str!("../fixtures/shl.json"),
            include_str!("../fixtures/umul.json"),
            include_str!("../fixtures/umul_u32.json"),
            include_str!("../fixtures/umul_u8.json"),
            include_str!("../fixtures/wmul_i32_i64.json"),
            include_str!("../fixtures/wmul_u32_u64.json"),
            include_str!("../fixtures/step2b-batch2/char_is_ascii_digit.json"),
            include_str!("../fixtures/step2b-batch2/u8_is_ascii_alphabetic.json"),
            include_str!("../fixtures/step2b-batch2/u8_is_ascii_digit.json"),
            include_str!("../fixtures/step2b-batch2/u8_is_ascii_hexdigit.json"),
            include_str!("../fixtures/step2b-batch2/u8_is_ascii_lowercase.json"),
        ]
        .into_iter()
        .map(|json| serde_json::from_str(json).expect("a committed fixture deserializes"))
        .collect()
    }

    /// Both walks, every target in `0..=probe_max` (past the last real block on
    /// purpose), one memo for the whole function. Returns how many guard
    /// answers were non-empty and how many reachability answers were `Some`,
    /// so a caller can prove the shape exercised the walks.
    fn agree_on_every_target(
        shape: &str,
        f: &VerifiableFunction,
        probe_max: usize,
    ) -> (usize, usize) {
        let mut memo = FunctionScanMemo::new(f);
        let (mut guards_non_empty, mut reach_some) = (0, 0);
        for t in 0..=probe_max {
            let guards = reconstruct_sound_dominating_guards_memo(&mut memo, BlockId(t));
            let reference = reconstruct_sound_dominating_guards_reference(f, BlockId(t));
            assert_eq!(guards, reference, "{shape}: dominating guards differ on target bb{t}");
            let reach = reconstruct_reachability_condition_memo(&mut memo, BlockId(t));
            let reference = reconstruct_reachability_condition_reference(f, BlockId(t));
            assert_eq!(reach, reference, "{shape}: reachability differs on target bb{t}");
            guards_non_empty += usize::from(!guards.is_empty());
            reach_some += usize::from(reach.is_some());
        }
        (guards_non_empty, reach_some)
    }

    #[test]
    fn matches_reference_on_the_fixture_corpus() {
        let corpus = corpus();
        assert!(corpus.len() >= 25);
        let (mut guards, mut reach) = (0, 0);
        for f in &corpus {
            let (g, r) = agree_on_every_target(&f.def_path, f, f.body.blocks.len() + 1);
            guards += g;
            reach += r;
        }
        assert!(guards > 0, "the corpus must exercise a non-empty guard answer");
        assert!(reach > 0, "the corpus must exercise a Some reachability answer");
    }

    fn int_local(index: usize, name: Option<&str>) -> LocalDecl {
        LocalDecl { index, ty: Ty::i32(), name: name.map(str::to_string) }
    }

    fn bool_local(index: usize, name: &str) -> LocalDecl {
        LocalDecl { index, ty: Ty::Bool, name: Some(name.to_string()) }
    }

    fn build(
        locals: Vec<LocalDecl>,
        blocks: Vec<TrustBlock>,
        arg_count: usize,
    ) -> VerifiableFunction {
        VerifiableFunction {
            name: "g".into(),
            def_path: "test::g".into(),
            span: SourceSpan::default(),
            body: VerifiableBody {
                locals,
                blocks,
                arg_count,
                return_ty: Ty::i32(),
                datatype_defs: Default::default(),
            },
            contracts: vec![],
            preconditions: vec![],
            postconditions: vec![],
            spec: Default::default(),
            tuple_layouts: Default::default(),
        }
    }

    fn blk(id: usize, stmts: Vec<Statement>, terminator: Terminator) -> TrustBlock {
        TrustBlock { id: BlockId(id), stmts, terminator }
    }

    /// `SwitchInt(discr) { 0 => val0, _ => otherwise }` — the bool-`if` shape.
    fn switch(discr_local: usize, val0: usize, otherwise: usize) -> Terminator {
        Terminator::SwitchInt {
            exhaustive_enum_unreachable: false,
            discr: Operand::Copy(Place::local(discr_local)),
            targets: vec![(0u128, BlockId(val0))],
            otherwise: BlockId(otherwise),
            span: SourceSpan::default(),
        }
    }

    fn assert_to(target: usize) -> Terminator {
        Terminator::Assert {
            cond: Operand::Copy(Place::local(1)),
            expected: true,
            msg: AssertMessage::BoundsCheck,
            target: BlockId(target),
            span: SourceSpan::default(),
            unwind: UnwindEdge::Unreachable,
        }
    }

    fn copy(dst: usize, src: usize) -> Statement {
        Statement::Assign {
            place: Place::local(dst),
            rvalue: Rvalue::Use(Operand::Copy(Place::local(src))),
            span: SourceSpan::default(),
        }
    }

    /// `k` diamonds `if b_j { assert; }` in a row. Cyclic when `looped` (a loop
    /// header before them and a back edge after them) — the `ay_milp` shape,
    /// where the reference expanded 2^(k-j) paths beneath every assert; acyclic
    /// otherwise. `defs(j)` decides which blocks carry an integer definition, so
    /// the acyclic case exercises the destination summary: a name defined twice
    /// on one path must still bail exactly where the reference bailed.
    fn diamonds(
        k: usize,
        looped: bool,
        defs: impl Fn(usize) -> Option<(usize, usize)>,
    ) -> VerifiableFunction {
        // locals: _0 ret, _1 cond, _2.._5 ints (params), b_j bools, then temporaries.
        let mut locals = vec![
            int_local(0, None),
            bool_local(1, "cond"),
            int_local(2, Some("p")),
            int_local(3, Some("q")),
            int_local(4, Some("r")),
            int_local(5, Some("s")),
        ];
        let first_bool = locals.len();
        for j in 0..k {
            locals.push(bool_local(first_bool + j, &format!("b{j}")));
        }
        let first_tmp = locals.len();
        for j in 0..k {
            locals.push(int_local(first_tmp + j, None));
        }
        let mut blocks = Vec::new();
        // bb0: entry; looped: header switch(cond) {0 => exit, _ => first diamond}.
        let exit = 1 + 3 * k + 1;
        let diamond = |j: usize| 1 + 3 * j;
        if looped {
            blocks.push(blk(0, vec![], switch(1, exit, diamond(0))));
        } else {
            blocks.push(blk(0, vec![], Terminator::Goto(BlockId(diamond(0)))));
        }
        for j in 0..k {
            let d = diamond(j);
            let stmts = defs(j).map(|(dst, src)| vec![copy(dst, src)]).unwrap_or_default();
            // D_j: switch(b_j) {0 => J_j, _ => T_j}; T_j: assert → J_j; J_j: → next.
            blocks.push(blk(d, stmts, switch(first_bool + j, d + 2, d + 1)));
            blocks.push(blk(d + 1, vec![], assert_to(d + 2)));
            let next = if j + 1 < k {
                diamond(j + 1)
            } else if looped {
                0
            } else {
                exit
            };
            blocks.push(blk(d + 2, vec![], Terminator::Goto(BlockId(next))));
        }
        blocks.push(blk(exit, vec![], Terminator::Return));
        build(locals, blocks, 5 + k)
    }

    #[test]
    fn matches_reference_on_a_loop_of_diamonds() {
        // 10 diamonds: the reference enumerates up to 2^9 paths beneath the first
        // assert, cheap enough to run as an oracle here, expensive enough that the
        // pruned walk had to differ in work to differ at all.
        let f = diamonds(10, true, |_| None);
        let (guards, reach) =
            agree_on_every_target("loop of diamonds", &f, f.body.blocks.len() + 1);
        assert!(guards > 0);
        assert!(reach > 0, "a loop body target has a reachability condition");
    }

    #[test]
    fn matches_reference_on_an_acyclic_chain_with_definitions() {
        // Every diamond defines its own temporary from a parameter: no name is
        // defined twice, so the reachability condition stays `Some` and carries the
        // definitions.
        let f = diamonds(9, false, |j| Some((15 + j, 2 + (j % 4))));
        let (guards, reach) = agree_on_every_target("acyclic chain", &f, f.body.blocks.len() + 1);
        assert!(guards > 0);
        assert!(reach > 0);
    }

    #[test]
    fn matches_reference_when_a_pruned_subtree_redefines_a_destination() {
        // Diamonds 2 and 7 both define `_15`. For an assert in diamonds 0..=2 the
        // second definition lies BENEATH a pruned edge (the reference found it by
        // walking there and bailed); for an assert in diamonds 3..=7 it lies on the
        // path itself; after 7 both are on the path. Every case must bail, or not,
        // exactly as the reference did — that is the destination summary's whole job.
        let f = diamonds(9, false, |j| match j {
            2 | 7 => Some((15, 2)),
            _ => None,
        });
        let (guards, _) = agree_on_every_target("pruned redefinition", &f, f.body.blocks.len() + 1);
        assert!(guards > 0);
        // And the redefinition really does bail somewhere: the assert of diamond 0
        // sees `_15` defined twice beneath its pruned else-edge.
        assert_eq!(reconstruct_reachability_condition(&f, BlockId(2)), None);
        // A single definition beneath the pruned edge does not.
        let single = diamonds(9, false, |j| (j == 7).then_some((15, 2)));
        assert!(reconstruct_reachability_condition(&single, BlockId(2)).is_some());
    }

    #[test]
    fn matches_reference_on_duplicate_ids_and_dangling_successors() {
        // bb1 appears twice (the walks resolve the FIRST); bb9 is a dangling successor.
        let locals = vec![int_local(0, None), bool_local(1, "cond"), bool_local(2, "b")];
        let blocks = vec![
            blk(0, vec![], switch(2, 1, 3)),
            blk(1, vec![], Terminator::Goto(BlockId(3))),
            blk(1, vec![], Terminator::Goto(BlockId(9))),
            blk(3, vec![], switch(1, 9, 4)),
            blk(4, vec![], assert_to(5)),
            blk(5, vec![], Terminator::Return),
        ];
        let f = build(locals, blocks, 2);
        let (guards, reach) = agree_on_every_target("duplicate ids", &f, 10);
        assert!(guards > 0);
        assert!(reach > 0);
    }
}

/// THE BRIDGE HALF of the never-typed-divergence admission
/// (`trust_mir_extract::convert::direct_callee_returns_never`).
///
/// The extractor now routes a DIRECT call whose callee rustc types `-> !` to
/// `Terminator::Call { target: None }` instead of the `Terminator::Opaque` bail.
/// `Opaque` was a hard `Err(UnsupportedOp)` at this bridge; `Call { target: None }`
/// is not, so every such call now walks into the Call arm. These rows pin what
/// happens to it, and — the load-bearing part — that NO row lowers to a module
/// `trust_ir_build::validate_module` rejects while `lower_to_trust_ir` says `Ok`.
///
/// The defect these rows exist to prevent, measured on this tree before the
/// tripwire in `lower_terminator`: a nounwind no-normal-target call
/// (`unwind: Unreachable`/`Continue`/`Terminate`) fell past the recognized
/// panic/UB/abort arm, took the absent-callee may-panic encoding
/// (`Const Bool(false)` + `Assert`), reached the `if let Some(cont) = target`
/// branch-emission with `target: None`, and emitted NOTHING to end the block —
/// and `wire_cleanup_edge` had no cleanup successor to wire either. The module
/// came back `Ok` with a bb0 holding exactly
/// `[Const { ty: Bool, value: Bool(false) }, Assert { cond: %2 }]`, on which
/// `validate_module` reports both `BlockMissingTerminator(0)` ("bb0 has no
/// terminator instruction") and `MissingTerminator { block: 0 }` ("bb0: last
/// instruction is not a terminator").
#[cfg(test)]
mod never_typed_diverging_call_bridge_tests {
    use trust_ir::Module;
    use trust_ir::inst::Inst;
    use trust_types::{
        BasicBlock as TrustBlock, BlockId, ConstValue, LocalDecl, Operand, Place, Rvalue,
        Statement, Terminator, Ty, UnwindEdge, VerifiableBody, VerifiableFunction,
    };

    use super::{BridgeError, lower_to_trust_ir};

    /// A one-block body whose terminator is a call to `callee` with NO
    /// normal-return target, under `unwind`. `cleanup` adds the bb1 the
    /// `UnwindEdge::Cleanup` row needs.
    fn diverging_call_body(callee: &str, unwind: UnwindEdge, cleanup: bool) -> VerifiableFunction {
        let mut blocks = vec![TrustBlock {
            id: BlockId(0),
            stmts: vec![],
            terminator: Terminator::Call {
                unwind,
                is_unsafe_sig: false,
                callee_identity: None,
                callee_key: None,
                is_foreign: false,
                func: callee.to_string(),
                args: vec![],
                dest: Place::local(1),
                target: None,
                atomic: None,
                span: Default::default(),
            },
        }];
        if cleanup {
            // A REAL cleanup pad, not the lone-`resume` no-op landing pad
            // `is_noop_landing_pad` (and therefore `modelled_cleanup_target`)
            // deliberately declines to model: one statement is enough to make it
            // a behaviour rather than a built-phase artifact.
            blocks.push(TrustBlock {
                id: BlockId(1),
                stmts: vec![Statement::Assign {
                    place: Place::local(0),
                    rvalue: Rvalue::Use(Operand::Constant(ConstValue::Unit)),
                    span: Default::default(),
                }],
                terminator: Terminator::Resume,
            });
        }
        VerifiableFunction {
            name: "probe".into(),
            def_path: "mycrate::probe".into(),
            span: Default::default(),
            body: VerifiableBody {
                locals: vec![
                    LocalDecl { index: 0, ty: Ty::Unit, name: None },
                    // rustc's destination local for a `-> !` callee.
                    LocalDecl { index: 1, ty: Ty::Never, name: None },
                ],
                blocks,
                arg_count: 0,
                return_ty: Ty::Unit,
                datatype_defs: Default::default(),
            },
            contracts: vec![],
            preconditions: vec![],
            postconditions: vec![],
            spec: Default::default(),
            tuple_layouts: Default::default(),
        }
    }

    /// THE INVARIANT EVERY ROW BELOW IS MEASURED AGAINST: an `Ok` from the bridge
    /// must be a module the trust-ir validator accepts. Nothing in `compiler/`
    /// calls `validate_module`, so an `Ok`-reported invalid module is caught
    /// nowhere downstream — it has to be caught here.
    fn lowered_module(result: Result<Module, BridgeError>) -> Result<Module, BridgeError> {
        if let Ok(module) = &result {
            let errors = trust_ir_build::validate_module(module);
            assert!(
                errors.is_empty(),
                "the bridge reported `Ok` on a module `validate_module` rejects — the one \
                 outcome that is never acceptable, because no consumer in `compiler/` \
                 revalidates: {errors:?}"
            );
        }
        result
    }

    fn refusal_detail(result: Result<Module, BridgeError>) -> String {
        match result {
            Err(BridgeError::UnsupportedOp(detail)) => detail,
            other => panic!("expected an explicit `UnsupportedOp` refusal, got {other:?}"),
        }
    }

    /// CORRECTED 2026-09-26 (T2). This module's first three rows used to pin a
    /// REFUSAL of every nounwind `!`-typed call site that is not a recognized halt
    /// (`mycrate::never_returns` in three unwind spellings, `std::process::exit`,
    /// and the same call to a bundled callee). Those calls now lower as
    /// `call; unreachable` — the extractor admits them on rustc's never-type fact
    /// and the bridge ends the block on the `!`-typed destination — and the rows
    /// that pin that lowering, execute it, and check the absent-callee marker are
    /// `tests/producer_lowering_gaps.rs` (the T2 rows). What stays HERE is the
    /// refusal the correction did not remove.
    /// THE REFUSAL THAT REMAINS. A `target: None` call whose destination can hold a
    /// VALUE has no licence for `Unreachable` — only a `!`-typed result says control
    /// never comes back — so a hand-built or forged body of that shape is still
    /// refused by name, in all three nounwind spellings, rather than lowered to a
    /// module missing its terminator.
    #[test]
    fn a_nounwind_no_target_call_with_a_value_destination_is_still_refused_by_name() {
        for unwind in [UnwindEdge::Unreachable, UnwindEdge::Continue, UnwindEdge::Terminate] {
            let mut func = diverging_call_body("mycrate::returns_unit", unwind.clone(), false);
            func.body.locals[1].ty = Ty::Unit;
            let detail = refusal_detail(lowered_module(lower_to_trust_ir(&func)));
            assert!(
                detail.contains("mycrate::returns_unit")
                    && detail.contains("no normal-return target")
                    && detail.contains("no no-return call terminator"),
                "the refusal must NAME the shape it refuses ({unwind:?}): {detail}"
            );
        }
    }

    /// THE BOUNDARY, and why the refusal is not a blanket ban on `target: None`.
    /// A RECOGNIZED panic terminal at a diverging site keeps its established
    /// `assert(false)` + `Inst::Unreachable` encoding — the charge "prove this
    /// site unreachable" — and validates.
    #[test]
    fn a_recognized_panic_terminal_still_lowers_and_validates() {
        let func = diverging_call_body("core::panicking::panic", UnwindEdge::Unreachable, false);
        let module = lowered_module(lower_to_trust_ir(&func)).expect("a panic terminal lowers");
        let entry = &module.functions[0].blocks[0];
        assert!(
            matches!(entry.body.last().map(|node| &node.inst), Some(Inst::Unreachable)),
            "{:?}",
            entry.body
        );
    }

    /// THE OTHER BOUNDARY: a no-normal-target call whose unwind edge supplies a
    /// modelled CLEANUP successor already ends its block — `wire_cleanup_edge`
    /// branches to the cleanup block — so it is lowered, not refused. This is the
    /// shape the bulk-allocation-sink admission in the extractor relies on, and
    /// the tripwire must not take it away.
    #[test]
    fn a_no_target_call_with_a_cleanup_edge_still_lowers_and_validates() {
        let func =
            diverging_call_body("mycrate::never_returns", UnwindEdge::Cleanup(BlockId(1)), true);
        let module = lowered_module(lower_to_trust_ir(&func))
            .expect("a cleanup successor terminates the block");
        let entry = &module.functions[0].blocks[0];
        assert!(
            matches!(entry.body.last().map(|node| &node.inst), Some(Inst::Br { .. })),
            "{:?}",
            entry.body
        );
    }

    /// THE CONTROL: an ordinary RETURNING call is untouched by any of this.
    #[test]
    fn a_returning_call_is_unchanged() {
        let mut func = diverging_call_body("mycrate::plain", UnwindEdge::Unreachable, false);
        func.body.locals[1].ty = Ty::Unit;
        func.body.blocks[0].terminator = Terminator::Call {
            unwind: UnwindEdge::Unreachable,
            is_unsafe_sig: false,
            callee_identity: None,
            callee_key: None,
            is_foreign: false,
            func: "mycrate::plain".into(),
            args: vec![],
            dest: Place::local(1),
            target: Some(BlockId(1)),
            atomic: None,
            span: Default::default(),
        };
        func.body.blocks.push(TrustBlock {
            id: BlockId(1),
            stmts: vec![],
            terminator: Terminator::Return,
        });
        let module =
            lowered_module(lower_to_trust_ir(&func)).expect("a returning call still lowers");
        assert_eq!(module.functions.len(), 1);
    }
}

/// Exact local-stability answers for cross-consumer semantic regressions.
#[doc(hidden)]
pub fn local_stability_for_test(
    func: &VerifiableFunction,
    local: usize,
) -> (bool, bool, bool, bool) {
    let mut memo = FunctionScanMemo::new(func);
    let _ = memo.copy_source_is_single_valued(local);
    (
        native_local_is_stable(func, local),
        copy_source_is_single_valued(func, local),
        local_value_is_stable(func, local),
        memo.copy_source_is_single_valued(local),
    )
}

/// Native arithmetic-fact gate, exposed only for semantic regressions.
#[doc(hidden)]
pub fn native_math_stability_for_test(func: &VerifiableFunction, local: usize) -> bool {
    native_is_single_assignment(func, local)
}

#[cfg(test)]
mod wave488_perf_tests {
    use super::*;

    #[test]
    fn wave488_local_decl_by_index_and_with_set_reads_match_dense_and_sparse_locals() {
        let dense = vec![
            LocalDecl { index: 0, ty: Ty::i32(), name: None },
            LocalDecl { index: 1, ty: Ty::u64(), name: Some("MEM".into()) },
            LocalDecl { index: 2, ty: Ty::Bool, name: Some("flag".into()) },
            LocalDecl { index: 3, ty: Ty::u32(), name: Some("flag".into()) },
            LocalDecl { index: 4, ty: Ty::u16(), name: Some("uniq".into()) },
        ];
        for i in 0..dense.len() {
            assert_eq!(local_decl_by_index(&dense, i).map(|d| d.index), Some(i));
        }
        assert!(local_decl_by_index(&dense, 99).is_none());
        assert_eq!(collision_safe_local_name(&dense, 2), "_2");
        assert_eq!(collision_safe_local_name(&dense, 4), "uniq");

        let mut sparse = dense.clone();
        sparse.swap(1, 3);
        sparse[4].index = 10;
        assert_eq!(local_decl_by_index(&sparse, 1).map(|d| &d.ty), Some(&Ty::u64()));
        assert_eq!(local_decl_by_index(&sparse, 3).map(|d| &d.ty), Some(&Ty::u32()));
        assert_eq!(local_decl_by_index(&sparse, 10).map(|d| &d.ty), Some(&Ty::u16()));
        assert!(local_decl_by_index(&sparse, 4).is_none());

        let mut mod_dense = Module::new("m_dense");
        let mut cache_dense = FxHashMap::default();
        let kf = FxHashMap::default();
        let ks = FxHashMap::default();
        let ce = ClosureEnvTypes::default();
        let ctx_dense = LoweringCtx::new(
            &dense,
            2,
            TrustIrBlockId::new(0),
            &mut mod_dense,
            &kf,
            &ks,
            &ce,
            &mut cache_dense,
            "test::dense",
            &[],
        );
        assert!(ctx_dense.local_is_lifted_memory_state_carrier(1));
        assert!(!ctx_dense.local_is_lifted_memory_state_carrier(2));
        assert_eq!(ctx_dense.local_values.get(&1), Some(&ValueId::new(0)));
        assert_eq!(ctx_dense.local_values.get(&2), Some(&ValueId::new(1)));
        assert_eq!(ctx_dense.local_values.get(&0), Some(&ValueId::new(2)));
        assert!(byte_slice_fat_ty(&ctx_dense).is_ok());

        let mut mod_sparse = Module::new("m_sparse");
        let mut cache_sparse = FxHashMap::default();
        let ctx_sparse = LoweringCtx::new(
            &sparse,
            2,
            TrustIrBlockId::new(0),
            &mut mod_sparse,
            &kf,
            &ks,
            &ce,
            &mut cache_sparse,
            "test::sparse",
            &[],
        );
        assert!(ctx_sparse.local_is_lifted_memory_state_carrier(1));
        assert_eq!(ctx_sparse.local_values.get(&1), Some(&ValueId::new(0)));
        assert_eq!(ctx_sparse.local_values.get(&2), Some(&ValueId::new(1)));
        assert_eq!(ctx_sparse.local_values.get(&0), Some(&ValueId::new(2)));
        assert_eq!(ctx_sparse.local_values.get(&3), Some(&ValueId::new(3)));
        assert_eq!(ctx_sparse.local_values.get(&10), Some(&ValueId::new(4)));
    }
}
